select ac_cargar_unidad($ac${"slug":"animales-1","rama":"animales","orden":1,"nivel":1,"titulo_es":"La trama de la vida","bajada_es":"Genes, especies y ecosistemas: qué es la biodiversidad, cómo se conectan los seres vivos y por qué perder una especie mueve toda la red.","objetivos_es":["Definir la biodiversidad en sus tres niveles","Armar cadenas y redes tróficas con productores, consumidores y descomponedores","Explicar el papel de las especies clave y los ingenieros de ecosistemas","Relacionar adaptaciones de animales argentinos con su ambiente","Reconocer los servicios que la fauna presta a las personas"],"repasa":["tronco-1"],"requiere_tronco":1,"fuentes":["ipbes-global","iucn-red-list","sib-apn","sarem-2019","aves-argentinas","parques-nacionales","gbif"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"animales-1.s1","orden":1,"tipo":"leccion","titulo_es":"Qué es la biodiversidad","bajada_es":"Genes, especies y ecosistemas: tres niveles de la variedad de la vida.","minutos":11,"pasos":[{"slug":"animales-1.s1.p1","orden":1,"grupo":"animales-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tres niveles","cuerpo":["Biodiversidad es la variedad de la vida en todas sus formas. Se mira en tres niveles: la diversidad genética (las diferencias entre individuos de una misma especie), la diversidad de especies (cuántas y cuáles especies hay) y la diversidad de ecosistemas (selvas, pastizales, humedales, mares).","Los tres importan. Una especie con poca diversidad genética es más vulnerable a enfermedades o cambios del clima. Un paisaje con un solo tipo de ecosistema ofrece menos hábitats."]},"solucion":{}},{"slug":"animales-1.s1.p2","orden":2,"grupo":"animales-1.s1.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿A qué nivel de la biodiversidad se refiere cada ejemplo?","grupos":[{"id":"g1","nombre":"Genética"},{"id":"g2","nombre":"De especies"},{"id":"g3","nombre":"De ecosistemas"}],"items":[{"id":"i1","texto":"Los distintos colores de pelaje en una población de zorros"},{"id":"i2","texto":"Las aves distintas que viven en una laguna"},{"id":"i3","texto":"Selvas, humedales y estepas en un mismo país"},{"id":"i4","texto":"Las muchas variedades de maíz de los pueblos andinos"},{"id":"i5","texto":"La cantidad de especies de ranas en las Yungas"},{"id":"i6","texto":"Bosques y pastizales en una misma provincia"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"La biodiversidad no es solo contar especies: también son las diferencias dentro de ellas y entre paisajes."}},{"slug":"animales-1.s1.p3","orden":3,"grupo":"animales-1.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuántas especies hay","cuerpo":["La ciencia describió alrededor de 2 millones de especies, pero se estima que existen muchas más: solo de animales, plantas, hongos y otros organismos con células complejas podría haber alrededor de 8 a 9 millones. La mayoría son insectos y otros invertebrados, muchos todavía sin nombre.","Argentina, con su enorme variedad de climas, tiene alrededor de 1.000 especies de aves y unas 400 de mamíferos, además de miles de especies de plantas, peces, anfibios, reptiles e invertebrados."],"destacado":{"valor":"≈ 1.000","texto":"especies de aves viven en Argentina: una de las avifaunas más ricas del mundo."}},"solucion":{}},{"slug":"animales-1.s1.p4","orden":4,"grupo":"animales-1.s1.p4","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas especies de seres vivos describió la ciencia hasta hoy.","min":10000,"max":100000000,"paso":1,"unidad":"especies","escala":"log"},"solucion":{"valor":2000000,"banda":"log","explicacion":"Alrededor de 2 millones. Y se estima que existen varias veces más, sobre todo insectos y organismos chicos."}},{"slug":"animales-1.s1.p5","orden":5,"grupo":"animales-1.s1.p5","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos grupos de animales por cantidad de especies descriptas en el mundo, de más a menos.","items":[{"id":"i1","texto":"Insectos"},{"id":"i2","texto":"Peces"},{"id":"i3","texto":"Aves"},{"id":"i4","texto":"Mamíferos"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Los insectos dominan la biodiversidad animal. Los mamíferos, el grupo que más miramos, son una fracción mínima.","valores":{"i1":"alrededor de un millón","i2":"más de 30.000","i3":"unas 11.000","i4":"unas 6.500"}}},{"slug":"animales-1.s1.p6","orden":6,"grupo":"animales-1.s1.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La mayoría de las especies del planeta ya fueron descubiertas y descriptas por la ciencia.","razones":[{"id":"r1","texto":"Porque se estima que existen varias veces más de las descriptas"},{"id":"r2","texto":"Porque ya no quedan lugares por explorar"},{"id":"r3","texto":"Porque todas las especies son grandes y fáciles de ver"}]},"solucion":{"valor":false,"explicacion":"Se describieron alrededor de 2 millones, pero se estima que existen varias veces más. Cada año se describen miles de especies nuevas.","clave":["r1"]}},{"slug":"animales-1.s1.p7","orden":7,"grupo":"animales-1.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué importa la variedad","cuerpo":["Un ecosistema con muchas especies suele ser más estable: si una especie falla por una sequía o una enfermedad, otras pueden cumplir funciones parecidas. Es como una red con muchos hilos: si se corta uno, no se cae todo.","La biodiversidad también es la fuente de alimentos, medicinas, materiales y de muchos servicios que la naturaleza da gratis, como la polinización o el control de plagas."]},"solucion":{}},{"slug":"animales-1.s1.p8","orden":8,"grupo":"animales-1.s1.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué un cultivo con una sola variedad es más frágil.","items":[{"id":"i1","texto":"Todas las plantas del campo son genéticamente iguales"},{"id":"i2","texto":"Aparece una enfermedad que afecta a esa variedad"},{"id":"i3","texto":"Ninguna planta tiene defensas distintas"},{"id":"i4","texto":"Se pierde todo el cultivo"},{"id":"i5","texto":"Las plantas iguales se protegen entre sí"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La diversidad genética es un seguro. Por eso se conservan semillas de muchas variedades en bancos de germoplasma."}},{"slug":"animales-1.s1.p9","orden":9,"grupo":"animales-1.s1.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué beneficios trae la biodiversidad a las personas? Marcá todos.","opciones":[{"id":"o1","texto":"Alimentos variados"},{"id":"o2","texto":"Medicinas"},{"id":"o3","texto":"Polinización de cultivos"},{"id":"o4","texto":"Ecosistemas más estables"},{"id":"o5","texto":"Más enfermedades en los cultivos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La biodiversidad es la base de lo que comemos, de muchos remedios y de la estabilidad de los ecosistemas."}},{"slug":"animales-1.s1.p10","orden":10,"grupo":"animales-1.s1.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada ecosistema argentino con un animal característico.","izquierda":[{"id":"a1","texto":"Selva Paranaense"},{"id":"a2","texto":"Estepa Patagónica"},{"id":"a3","texto":"Esteros del Iberá"},{"id":"a4","texto":"Altos Andes"}],"derecha":[{"id":"b1","texto":"Yaguareté"},{"id":"b2","texto":"Guanaco"},{"id":"b3","texto":"Ciervo de los pantanos"},{"id":"b4","texto":"Cóndor andino"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada ecosistema tiene su fauna. La diversidad de ecosistemas trae diversidad de especies."}},{"slug":"animales-1.s1.p11","orden":11,"grupo":"animales-1.s1.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La biodiversidad incluye genes, especies y ecosistemas."},{"id":"s2","texto":"Biodiversidad es solo la cantidad de animales grandes de un lugar."},{"id":"s3","texto":"Argentina tiene alrededor de 1.000 especies de aves."},{"id":"s4","texto":"Un ecosistema con menos especies es más estable."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La biodiversidad es mucho más que los animales que vemos.","por_opcion":{"s2":"Incluye todos los seres vivos y los tres niveles, no solo animales grandes.","s4":"Suele ser al revés: más especies dan más estabilidad."}}},{"slug":"animales-1.s1.p12","orden":12,"grupo":"animales-1.s1.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se describieron 2 millones de especies y se estima que existen 8 millones, ¿qué porcentaje conocemos?","unidad":"%","decimales":0},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"2 ÷ 8 × 100 = 25 %. La mayor parte de la vida del planeta todavía no tiene nombre científico."}},{"slug":"animales-1.s1.p12.v2","orden":12,"grupo":"animales-1.s1.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se describieron 2 millones de especies y se estima que existen 10 millones, ¿qué porcentaje conocemos?","unidad":"%","decimales":0},"solucion":{"valor":20,"tolerancia":0.5,"explicacion":"2 ÷ 10 × 100 = 20 %. La mayor parte de la vida del planeta todavía no tiene nombre científico."}},{"slug":"animales-1.s1.p12.v3","orden":12,"grupo":"animales-1.s1.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se describieron 1,5 millones de especies y se estima que existen 6 millones, ¿qué porcentaje conocemos?","unidad":"%","decimales":0},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"1,5 ÷ 6 × 100 = 25 %. La mayor parte de la vida del planeta todavía no tiene nombre científico."}},{"slug":"animales-1.s1.p13","orden":13,"grupo":"animales-1.s1.p13","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una especie con poca diversidad genética es más vulnerable a una enfermedad nueva.","razones":[{"id":"r1","texto":"Porque sin variación, lo que afecta a uno afecta a casi todos"},{"id":"r2","texto":"Porque las enfermedades no afectan a los animales"},{"id":"r3","texto":"Porque la diversidad genética aumenta las enfermedades"}]},"solucion":{"valor":true,"explicacion":"Si todos los individuos son parecidos, una enfermedad que afecta a uno puede afectar a casi todos. La variación genética es un seguro.","clave":["r1"]}},{"slug":"animales-1.s1.p14","orden":14,"grupo":"animales-1.s1.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La biodiversidad se mira en tres niveles: {{0}}, de {{1}} y de {{2}}.","banco":[{"id":"w1","texto":"genética"},{"id":"w2","texto":"especies"},{"id":"w3","texto":"ecosistemas"},{"id":"w4","texto":"química"},{"id":"w5","texto":"ciudades"},{"id":"w6","texto":"climas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Los tres niveles de la variedad de la vida, en una sola línea."}}]},{"slug":"animales-1.s2","orden":2,"tipo":"leccion","titulo_es":"Quién come a quién","bajada_es":"Productores, consumidores y descomponedores: cadenas y redes tróficas con animales argentinos.","minutos":11,"pasos":[{"slug":"animales-1.s2.p1","orden":1,"grupo":"animales-1.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los papeles de la red","cuerpo":["En un ecosistema, los productores —plantas, algas— fabrican su alimento con la luz del sol. Los consumidores comen a otros seres vivos: los herbívoros comen plantas, los carnívoros comen animales y los omnívoros comen de todo. Los descomponedores —hongos, bacterias, lombrices— transforman los restos de los seres muertos en nutrientes que vuelven al suelo.","Una cadena trófica muestra quién come a quién en línea: pasto, cuis, zorro. Pero en la realidad, cada especie come y es comida por varias: se forma una red trófica."]},"solucion":{}},{"slug":"animales-1.s2.p2","orden":2,"grupo":"animales-1.s2.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué papel cumple cada ser vivo en el ecosistema?","grupos":[{"id":"g1","nombre":"Productor"},{"id":"g2","nombre":"Consumidor"},{"id":"g3","nombre":"Descomponedor"}],"items":[{"id":"i1","texto":"Pasto del pastizal"},{"id":"i2","texto":"Ñandú"},{"id":"i3","texto":"Hongos del suelo"},{"id":"i4","texto":"Algas de una laguna"},{"id":"i5","texto":"Puma"},{"id":"i6","texto":"Lombrices"},{"id":"i7","texto":"Carpincho"},{"id":"i8","texto":"Bacterias"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3","i7":"g2","i8":"g3"},"explicacion":"Sin productores no entra energía; sin descomponedores, los nutrientes no vuelven al suelo."}},{"slug":"animales-1.s2.p3","orden":3,"grupo":"animales-1.s2.p3","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená esta cadena trófica del pastizal, del productor al último consumidor.","items":[{"id":"i1","texto":"Pasto"},{"id":"i2","texto":"Tucura (saltamontes)"},{"id":"i3","texto":"Sapo"},{"id":"i4","texto":"Culebra"},{"id":"i5","texto":"Aguilucho"}],"extremos":["Productor","Último consumidor"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La energía del sol entra por el pasto y va pasando, escalón por escalón, hasta el aguilucho."}},{"slug":"animales-1.s2.p4","orden":4,"grupo":"animales-1.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La energía se achica en cada escalón","cuerpo":["Como viste en el tronco, en cada escalón pasa alrededor del 10 % de la energía al siguiente: el resto se usa para vivir y se pierde como calor. Por eso hay mucho más pasto que tucuras, más tucuras que sapos y muy pocos aguiluchos.","También por eso los grandes carnívoros, como el puma o el yaguareté, necesitan territorios enormes: tienen que recorrer mucho para encontrar suficiente alimento."]},"solucion":{}},{"slug":"animales-1.s2.p5","orden":5,"grupo":"animales-1.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pastizal captura 10.000 unidades de energía. Si pasa el 10 % a cada escalón, ¿cuántas llegan al tercer escalón (pasto → herbívoro → carnívoro)?","unidad":"unidades","decimales":0},"solucion":{"valor":100,"tolerancia":2,"explicacion":"Herbívoros: 10.000 × 0,1 = 1.000. Carnívoros: × 0,1 = 100. Por eso hay tan pocos carnívoros grandes."}},{"slug":"animales-1.s2.p5.v2","orden":5,"grupo":"animales-1.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pastizal captura 50.000 unidades de energía. Si pasa el 10 % a cada escalón, ¿cuántas llegan al tercer escalón (pasto → herbívoro → carnívoro)?","unidad":"unidades","decimales":0},"solucion":{"valor":500,"tolerancia":10,"explicacion":"Herbívoros: 50.000 × 0,1 = 5.000. Carnívoros: × 0,1 = 500. Por eso hay tan pocos carnívoros grandes."}},{"slug":"animales-1.s2.p5.v3","orden":5,"grupo":"animales-1.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pastizal captura 100.000 unidades de energía. Si pasa el 10 % a cada escalón, ¿cuántas llegan al tercer escalón (pasto → herbívoro → carnívoro)?","unidad":"unidades","decimales":0},"solucion":{"valor":1000,"tolerancia":20,"explicacion":"Herbívoros: 100.000 × 0,1 = 10.000. Carnívoros: × 0,1 = 1.000. Por eso hay tan pocos carnívoros grandes."}},{"slug":"animales-1.s2.p6","orden":6,"grupo":"animales-1.s2.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un yaguareté necesita un territorio grande porque está en lo alto de la red trófica.","razones":[{"id":"r1","texto":"Porque llega poca energía a lo alto de la red"},{"id":"r2","texto":"Porque los yaguaretés comen pasto"},{"id":"r3","texto":"Porque no pueden dormir en el mismo lugar dos veces"}]},"solucion":{"valor":true,"explicacion":"Llega poca energía a lo alto de la red, así que un carnívoro grande necesita recorrer mucha superficie para encontrar presas suficientes.","clave":["r1"]}},{"slug":"animales-1.s2.p7","orden":7,"grupo":"animales-1.s2.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Redes, no cadenas","cuerpo":["En una laguna pampeana, las algas y las plantas acuáticas son comidas por caracoles, peces chicos y patos. Las mojarras comen insectos y plancton; las tarariras comen mojarras; las garzas comen mojarras, ranas y tarariras chicas; los biguás bucean por peces. Todos, al morir, alimentan a los descomponedores.","En una red, si una especie desaparece, las que la comían buscan otro alimento, y las que eran comidas por ella pueden multiplicarse. Los efectos viajan por los hilos de la red."]},"solucion":{}},{"slug":"animales-1.s2.p8","orden":8,"grupo":"animales-1.s2.p8","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de qué puede pasar si en una laguna se pescan casi todas las tarariras.","items":[{"id":"i1","texto":"Se pescan casi todas las tarariras"},{"id":"i2","texto":"Las mojarras tienen menos depredadores"},{"id":"i3","texto":"Aumenta mucho la cantidad de mojarras"},{"id":"i4","texto":"Las mojarras comen más plancton que filtra el agua"},{"id":"i5","texto":"El agua puede volverse más turbia"},{"id":"i6","texto":"Las mojarras se convierten en tarariras"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un cambio arriba de la red puede bajar en cascada hasta el agua. Es una cascada trófica."}},{"slug":"animales-1.s2.p9","orden":9,"grupo":"animales-1.s2.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada animal con lo que suele comer.","izquierda":[{"id":"a1","texto":"Carpincho"},{"id":"a2","texto":"Garza blanca"},{"id":"a3","texto":"Hornero"},{"id":"a4","texto":"Puma"}],"derecha":[{"id":"b1","texto":"Pastos y plantas acuáticas"},{"id":"b2","texto":"Peces y ranas"},{"id":"b3","texto":"Insectos y larvas"},{"id":"b4","texto":"Guanacos, liebres y otros mamíferos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada animal ocupa un lugar en la red según lo que come."}},{"slug":"animales-1.s2.p10","orden":10,"grupo":"animales-1.s2.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué pasaría en un bosque si desaparecieran todos los descomponedores?","opciones":[{"id":"o1","texto":"Se acumularían restos y faltarían nutrientes en el suelo"},{"id":"o2","texto":"Las plantas crecerían más rápido porque habría menos competencia"},{"id":"o3","texto":"No pasaría nada: los descomponedores no cumplen ninguna función"},{"id":"o4","texto":"Los animales vivirían más años"}]},"solucion":{"clave":["o1"],"explicacion":"Los descomponedores cierran el ciclo de la materia que viste en el tronco. Sin ellos, todo se detiene.","por_opcion":{"o3":"Son los que devuelven los nutrientes al suelo: sin ellos, el ciclo se corta."}}},{"slug":"animales-1.s2.p11","orden":11,"grupo":"animales-1.s2.p11","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos animales son omnívoros (comen plantas y animales)? Marcá todos.","opciones":[{"id":"o1","texto":"Zorro gris"},{"id":"o2","texto":"Comadreja overa"},{"id":"o3","texto":"Ñandú"},{"id":"o4","texto":"Puma"},{"id":"o5","texto":"Guanaco"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"El zorro, la comadreja y el ñandú comen frutos, semillas, insectos y pequeños animales. El puma es carnívoro; el guanaco, herbívoro."}},{"slug":"animales-1.s2.p12","orden":12,"grupo":"animales-1.s2.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los productores fabrican su alimento con la luz del sol."},{"id":"s2","texto":"Hay más aguiluchos que tucuras en un pastizal."},{"id":"s3","texto":"Los hongos son descomponedores."},{"id":"s4","texto":"Cada especie come a una sola especie y es comida por una sola."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Redes, no cadenas, y menos energía en cada escalón.","por_opcion":{"s2":"Es al revés: arriba de la red llega menos energía y hay menos individuos.","s4":"En la realidad se forman redes: cada especie come y es comida por varias."}}},{"slug":"animales-1.s2.p13","orden":13,"grupo":"animales-1.s2.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las plantas son {{0}}, los animales son {{1}} y los hongos y bacterias que reciclan restos son {{2}}.","banco":[{"id":"w1","texto":"productores"},{"id":"w2","texto":"consumidores"},{"id":"w3","texto":"descomponedores"},{"id":"w4","texto":"predadores"},{"id":"w5","texto":"parásitos"},{"id":"w6","texto":"polinizadores"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Los tres papeles básicos de cualquier ecosistema."}}]},{"slug":"animales-1.s3","orden":3,"tipo":"leccion","titulo_es":"Especies que sostienen a otras","bajada_es":"Depredadores tope, polinizadores e ingenieros de ecosistemas: algunas especies pesan mucho más que su número.","minutos":12,"pasos":[{"slug":"animales-1.s3.p1","orden":1,"grupo":"animales-1.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Especies clave","cuerpo":["Algunas especies tienen un efecto sobre el ecosistema mucho mayor de lo que haría pensar su cantidad: si desaparecen, el ecosistema cambia mucho. Se las llama especies clave.","Los depredadores tope, como el yaguareté o el puma, suelen ser especies clave: regulan a los herbívoros, que a su vez afectan a las plantas. Sin ellos, los herbívoros pueden multiplicarse y sobrepastorear."]},"solucion":{}},{"slug":"animales-1.s3.p2","orden":2,"grupo":"animales-1.s3.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de qué puede pasar cuando desaparece un depredador tope.","items":[{"id":"i1","texto":"Desaparece el depredador tope de una región"},{"id":"i2","texto":"Los herbívoros tienen menos depredadores"},{"id":"i3","texto":"Aumentan mucho los herbívoros"},{"id":"i4","texto":"Comen más plantas de las que se regeneran"},{"id":"i5","texto":"Cambia la vegetación y todo el ecosistema"},{"id":"i6","texto":"Las plantas se multiplican porque hay menos carnívoros"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un efecto en cascada que baja desde lo alto de la red hasta el suelo."}},{"slug":"animales-1.s3.p3","orden":3,"grupo":"animales-1.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ingenieros de ecosistemas","cuerpo":["Otras especies son ingenieras: modifican el ambiente y crean hábitats para otras. Las vizcachas cavan vizcacheras que usan muchos otros animales; los horneros construyen nidos que después ocupan otras aves; las lombrices airean y mezclan el suelo.","Pero un ingeniero también puede ser destructivo fuera de su lugar: el castor, traído de América del Norte a Tierra del Fuego, construye diques que inundan y matan bosques nativos que no evolucionaron con él."]},"solucion":{}},{"slug":"animales-1.s3.p4","orden":4,"grupo":"animales-1.s3.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada ingeniero con lo que hace.","izquierda":[{"id":"a1","texto":"Vizcacha"},{"id":"a2","texto":"Hornero"},{"id":"a3","texto":"Lombriz"},{"id":"a4","texto":"Castor en Tierra del Fuego"}],"derecha":[{"id":"b1","texto":"Cava cuevas que usan otros animales"},{"id":"b2","texto":"Construye nidos que después ocupan otras aves"},{"id":"b3","texto":"Airea y mezcla el suelo"},{"id":"b4","texto":"Hace diques que inundan bosques nativos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Los ingenieros cambian el ambiente. En su lugar de origen lo enriquecen; fuera de él, pueden destruirlo."}},{"slug":"animales-1.s3.p5","orden":5,"grupo":"animales-1.s3.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El castor es un ingeniero de ecosistemas que beneficia a los bosques de Tierra del Fuego.","razones":[{"id":"r1","texto":"Porque es invasor y sus diques matan bosques que no evolucionaron con él"},{"id":"r2","texto":"Porque los castores no construyen diques"},{"id":"r3","texto":"Porque en Tierra del Fuego no hay bosques"}]},"solucion":{"valor":false,"explicacion":"Allí es una especie exótica invasora: sus diques inundan y matan bosques de lenga y ñire que no evolucionaron con castores.","clave":["r1"]}},{"slug":"animales-1.s3.p6","orden":6,"grupo":"animales-1.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Polinizadores y dispersores","cuerpo":["Los polinizadores —abejas, mariposas, picaflores, murciélagos— permiten que se reproduzcan muchas plantas, incluidos cultivos. Los dispersores de semillas —aves, murciélagos, monos, tapires, zorros— llevan las semillas lejos de la planta madre.","Si faltan, las plantas que dependen de ellos dejan de reproducirse o se quedan en un solo lugar. En selvas donde se cazaron los grandes dispersores, algunos árboles de semillas grandes casi no logran regenerarse."]},"solucion":{}},{"slug":"animales-1.s3.p7","orden":7,"grupo":"animales-1.s3.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos animales pueden dispersar semillas? Marcá todos.","opciones":[{"id":"o1","texto":"Zorzal"},{"id":"o2","texto":"Tapir"},{"id":"o3","texto":"Murciélago frugívoro"},{"id":"o4","texto":"Zorro"},{"id":"o5","texto":"Lombriz"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Los animales que comen frutos llevan las semillas en su interior y las dejan lejos. Las lombrices mezclan el suelo, pero no dispersan semillas grandes."}},{"slug":"animales-1.s3.p8","orden":8,"grupo":"animales-1.s3.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué el yaguareté se considera una especie clave en la selva?","opciones":[{"id":"o1","texto":"Porque regula a sus presas, y eso mueve todo"},{"id":"o2","texto":"Porque es el animal más numeroso de la selva"},{"id":"o3","texto":"Porque dispersa las semillas de los árboles"},{"id":"o4","texto":"Porque come los frutos que caen al suelo"}]},"solucion":{"clave":["o1"],"explicacion":"Su efecto sobre el ecosistema es mucho mayor que su número, que es chico.","por_opcion":{"o3":"No es dispersor: su papel es el de depredador tope."}}},{"slug":"animales-1.s3.p9","orden":9,"grupo":"animales-1.s3.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Volver a traerlos","cuerpo":["Cuando una especie clave desaparece de una región, a veces se puede reintroducir. En los Esteros del Iberá, en Corrientes, proyectos de conservación reintrodujeron especies que habían desaparecido de la zona, como el oso hormiguero, el pecarí de collar, el guacamayo rojo, la nutria gigante y el yaguareté, que volvió a nacer en libertad allí después de décadas.","Esto se llama restauración o renaturalización: devolver a un ecosistema las piezas que le faltaban para que vuelva a funcionar."]},"solucion":{}},{"slug":"animales-1.s3.p10","orden":10,"grupo":"animales-1.s3.p10","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta especie fue reintroducida en los Esteros del Iberá o no?","grupos":[{"id":"g1","nombre":"Reintroducida"},{"id":"g2","nombre":"No (nunca desapareció de allí o no es de la zona)"}],"items":[{"id":"i1","texto":"Yaguareté"},{"id":"i2","texto":"Carpincho"},{"id":"i3","texto":"Oso hormiguero"},{"id":"i4","texto":"Yacaré"},{"id":"i5","texto":"Guacamayo rojo"},{"id":"i6","texto":"Pingüino de Magallanes"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Carpinchos y yacarés siguieron en los esteros. El pingüino es del mar patagónico, no de Corrientes."}},{"slug":"animales-1.s3.p11","orden":11,"grupo":"animales-1.s3.p11","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos efectos de reintroducir un depredador tope, del más inmediato al más lejano.","items":[{"id":"i1","texto":"Aparece un depredador que caza herbívoros"},{"id":"i2","texto":"Los herbívoros cambian su comportamiento y su número"},{"id":"i3","texto":"La vegetación se recupera en algunas zonas"},{"id":"i4","texto":"Se recupera la estructura completa del ecosistema"}],"extremos":["Más inmediato","Más lejano"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Los efectos de una especie clave se despliegan con el tiempo, como los retrasos que viste en el tronco.","valores":{"i1":"inmediato","i2":"meses a años","i3":"años","i4":"décadas"}}},{"slug":"animales-1.s3.p12","orden":12,"grupo":"animales-1.s3.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El yaguareté volvió a nacer en libertad en los Esteros del Iberá."},{"id":"s2","texto":"Los depredadores tope no afectan a las plantas."},{"id":"s3","texto":"Las vizcachas cavan cuevas que usan otros animales."},{"id":"s4","texto":"Todo ingeniero de ecosistemas es beneficioso en cualquier lugar."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Algunas especies pesan mucho más que su número. Y el contexto importa.","por_opcion":{"s2":"Al regular a los herbívoros, afectan indirectamente a la vegetación.","s4":"Fuera de su lugar de origen, como el castor en Tierra del Fuego, puede ser destructivo."}}},{"slug":"animales-1.s3.p13","orden":13,"grupo":"animales-1.s3.p13","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una especie con pocos individuos nunca puede ser importante para el ecosistema.","razones":[{"id":"r1","texto":"Porque algunas especies escasas tienen efectos enormes"},{"id":"r2","texto":"Porque solo importan las especies más abundantes"},{"id":"r3","texto":"Porque los depredadores tope son siempre los más numerosos"}]},"solucion":{"valor":false,"explicacion":"Las especies clave, como los depredadores tope, suelen ser pocas y sin embargo cambian todo el ecosistema.","clave":["r1"]}},{"slug":"animales-1.s3.p14","orden":14,"grupo":"animales-1.s3.p14","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos animales son ingenieros de ecosistemas? Marcá todos.","opciones":[{"id":"o1","texto":"Vizcacha"},{"id":"o2","texto":"Hornero"},{"id":"o3","texto":"Lombriz de tierra"},{"id":"o4","texto":"Castor"},{"id":"o5","texto":"Mariposa espejito"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Todos modifican el ambiente. El castor también, aunque en Tierra del Fuego para mal. La mariposa poliniza, pero no construye ni transforma el hábitat."}},{"slug":"animales-1.s3.p15","orden":15,"grupo":"animales-1.s3.p15","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un depredador {{0}} como el yaguareté regula a los herbívoros; un {{1}} de ecosistemas modifica el ambiente y crea hábitats para otros.","banco":[{"id":"w1","texto":"tope"},{"id":"w2","texto":"ingeniero"},{"id":"w3","texto":"exótico"},{"id":"w4","texto":"turista"},{"id":"w5","texto":"productor"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos ideas para entender por qué algunas especies importan tanto."}}]},{"slug":"animales-1.s4","orden":4,"tipo":"leccion","titulo_es":"Adaptados a su lugar","bajada_es":"Guanacos, pingüinos, playeros y peludos: cómo el cuerpo y el comportamiento de los animales responden a su ambiente.","minutos":12,"pasos":[{"slug":"animales-1.s4.p1","orden":1,"grupo":"animales-1.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué es una adaptación","cuerpo":["Una adaptación es una característica —del cuerpo, del funcionamiento o del comportamiento— que ayuda a un organismo a sobrevivir y reproducirse en su ambiente. Aparece a lo largo de muchas generaciones, por selección natural: los individuos con esa característica sobreviven y dejan más crías.","Las adaptaciones explican por qué cada ambiente tiene animales tan particulares."]},"solucion":{}},{"slug":"animales-1.s4.p2","orden":2,"grupo":"animales-1.s4.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ejemplos argentinos","cuerpo":["El guanaco tiene una sangre muy eficiente para captar oxígeno, lo que le permite vivir en la altura, y puede sobrevivir con poca agua en la estepa. El pingüino de Magallanes tiene plumas muy apretadas y grasa que lo aíslan del agua fría. El peludo (un tipo de armadillo) tiene un caparazón y garras para cavar. El ñandú, que no vuela, corre a gran velocidad por los pastizales."]},"solucion":{}},{"slug":"animales-1.s4.p3","orden":3,"grupo":"animales-1.s4.p3","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada animal con una adaptación a su ambiente.","izquierda":[{"id":"a1","texto":"Guanaco"},{"id":"a2","texto":"Pingüino de Magallanes"},{"id":"a3","texto":"Peludo"},{"id":"a4","texto":"Ñandú"}],"derecha":[{"id":"b1","texto":"Sangre eficiente para la altura y resistencia a la sequía"},{"id":"b2","texto":"Plumas apretadas y grasa contra el frío"},{"id":"b3","texto":"Garras para cavar madrigueras"},{"id":"b4","texto":"Patas largas para correr en el pastizal"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada adaptación responde a un desafío del ambiente: altura, frío, depredadores, distancias."}},{"slug":"animales-1.s4.p4","orden":4,"grupo":"animales-1.s4.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una adaptación del cuerpo o del comportamiento?","grupos":[{"id":"g1","nombre":"Del cuerpo"},{"id":"g2","nombre":"Del comportamiento"}],"items":[{"id":"i1","texto":"El pelaje blanco de invierno de algunos animales de montaña"},{"id":"i2","texto":"Migrar en invierno"},{"id":"i3","texto":"Las garras del peludo"},{"id":"i4","texto":"Cazar de noche"},{"id":"i5","texto":"El pico largo del picaflor"},{"id":"i6","texto":"Enterrarse en las horas de más calor"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las adaptaciones no son solo de forma: también son formas de actuar."}},{"slug":"animales-1.s4.p5","orden":5,"grupo":"animales-1.s4.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Grandes viajeros","cuerpo":["Algunas aves hacen migraciones enormes. El playero rojizo viaja cada año unos 15.000 kilómetros en cada sentido, entre el Ártico de Canadá, donde se reproduce, y la costa de Tierra del Fuego, donde pasa el verano austral. En el camino necesita parar en ciertas playas para alimentarse.","Si esas paradas se degradan, la especie no puede completar su viaje. Por eso la conservación de aves migratorias requiere cooperación entre muchos países."],"destacado":{"valor":"≈ 15.000 km","texto":"recorre en cada sentido el playero rojizo entre el Ártico y Tierra del Fuego."}},"solucion":{}},{"slug":"animales-1.s4.p6","orden":6,"grupo":"animales-1.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un playero rojizo recorre 15.000 km en su migración a un promedio de 500 km por día de vuelo, ¿cuántos días de vuelo necesita?","unidad":"días","decimales":0},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"15.000 ÷ 500 = 30 días de vuelo, sin contar las paradas para comer. Por eso las playas de descanso son vitales."}},{"slug":"animales-1.s4.p6.v2","orden":6,"grupo":"animales-1.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un playero rojizo recorre 15.000 km en su migración a un promedio de 600 km por día de vuelo, ¿cuántos días de vuelo necesita?","unidad":"días","decimales":0},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"15.000 ÷ 600 = 25 días de vuelo, sin contar las paradas para comer. Por eso las playas de descanso son vitales."}},{"slug":"animales-1.s4.p6.v3","orden":6,"grupo":"animales-1.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un playero rojizo recorre 15.000 km en su migración a un promedio de 750 km por día de vuelo, ¿cuántos días de vuelo necesita?","unidad":"días","decimales":0},"solucion":{"valor":20,"tolerancia":0.5,"explicacion":"15.000 ÷ 750 = 20 días de vuelo, sin contar las paradas para comer. Por eso las playas de descanso son vitales."}},{"slug":"animales-1.s4.p7","orden":7,"grupo":"animales-1.s4.p7","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué perder una playa de descanso afecta al playero rojizo.","items":[{"id":"i1","texto":"Se construye sobre una playa de descanso"},{"id":"i2","texto":"Los playeros no encuentran alimento en su viaje"},{"id":"i3","texto":"Llegan débiles o no llegan al destino"},{"id":"i4","texto":"Se reproducen menos y la población baja"},{"id":"i5","texto":"Los playeros aprenden a volar sin parar"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Una especie migratoria depende de una cadena de lugares. Si falla uno, falla todo el viaje."}},{"slug":"animales-1.s4.p8","orden":8,"grupo":"animales-1.s4.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un animal puede \"decidir\" adaptarse a un ambiente nuevo en pocos días.","razones":[{"id":"r1","texto":"Porque las adaptaciones aparecen en muchas generaciones"},{"id":"r2","texto":"Porque los animales nunca cambian"},{"id":"r3","texto":"Porque las adaptaciones las eligen los individuos"}]},"solucion":{"valor":false,"explicacion":"Las adaptaciones aparecen por selección natural a lo largo de muchas generaciones. Un individuo puede cambiar su comportamiento, pero no su cuerpo, de un día para otro.","clave":["r1"]}},{"slug":"animales-1.s4.p9","orden":9,"grupo":"animales-1.s4.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuando el ambiente cambia rápido","cuerpo":["Las adaptaciones funcionan para el ambiente en el que evolucionaron. Si el ambiente cambia muy rápido —por el cambio climático, un desmonte o una especie invasora—, muchas especies no tienen tiempo de adaptarse. Algunas pueden moverse a otros lugares; otras, no."]},"solucion":{}},{"slug":"animales-1.s4.p10","orden":10,"grupo":"animales-1.s4.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué el cambio climático rápido es un problema para muchas especies?","opciones":[{"id":"o1","texto":"Porque cambia más rápido de lo que pueden adaptarse"},{"id":"o2","texto":"Porque todas las especies prefieren el frío extremo"},{"id":"o3","texto":"Porque los animales no sienten la temperatura"},{"id":"o4","texto":"Porque los animales solo viven en ciudades"}]},"solucion":{"clave":["o1"],"explicacion":"La selección natural necesita generaciones. Si el ambiente cambia en décadas, muchas especies quedan desacopladas.","por_opcion":{"o3":"La sienten, y justamente sus adaptaciones dependen de ella."}}},{"slug":"animales-1.s4.p11","orden":11,"grupo":"animales-1.s4.p11","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué pueden hacer las especies ante un ambiente que cambia? Marcá las posibilidades.","opciones":[{"id":"o1","texto":"Moverse a otras zonas más adecuadas"},{"id":"o2","texto":"Cambiar algunos comportamientos"},{"id":"o3","texto":"Adaptarse si hay tiempo y variación genética"},{"id":"o4","texto":"Cambiar su cuerpo en una semana a voluntad"},{"id":"o5","texto":"Detener el cambio del clima"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Moverse, cambiar comportamientos o adaptarse en generaciones. Si ninguna alcanza, la especie declina."}},{"slug":"animales-1.s4.p12","orden":12,"grupo":"animales-1.s4.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El pingüino de Magallanes tiene plumas y grasa que lo aíslan del frío."},{"id":"s2","texto":"El guanaco se volvió resistente a la sequía porque quiso."},{"id":"s3","texto":"El playero rojizo migra miles de kilómetros."},{"id":"s4","texto":"Cualquier especie se adapta sin problema a cambios rápidos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Las adaptaciones son lentas. El problema actual es la velocidad del cambio.","por_opcion":{"s2":"Las adaptaciones aparecen por selección natural en muchas generaciones, no por voluntad.","s4":"Muchas no tienen tiempo de adaptarse a cambios muy rápidos."}}},{"slug":"animales-1.s4.p13","orden":13,"grupo":"animales-1.s4.p13","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un animal del Monte pasa las horas de más calor enterrado y sale a buscar comida de noche. ¿Qué tipo de adaptación es?","opciones":[{"id":"o1","texto":"Una adaptación de comportamiento"},{"id":"o2","texto":"Una adaptación de la forma del cuerpo"},{"id":"o3","texto":"Una costumbre que aprendió de las personas"},{"id":"o4","texto":"Una enfermedad que le impide salir de día"}]},"solucion":{"clave":["o1"],"explicacion":"Cambiar el horario de actividad es una de las adaptaciones más comunes en los desiertos.","por_opcion":{"o3":"Es una conducta heredada que lo ayuda a evitar el calor y perder menos agua."}}},{"slug":"animales-1.s4.p14","orden":14,"grupo":"animales-1.s4.p14","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué características ayudan a un animal a soportar el frío? Marcá todas.","opciones":[{"id":"o1","texto":"Una capa gruesa de grasa"},{"id":"o2","texto":"Pelaje o plumas densos"},{"id":"o3","texto":"Un cuerpo compacto"},{"id":"o4","texto":"Refugiarse en madrigueras"},{"id":"o5","texto":"Orejas enormes y finas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Las orejas grandes y finas sirven para perder calor: son típicas de animales de desiertos cálidos, no de zonas frías."}},{"slug":"animales-1.s4.p15","orden":15,"grupo":"animales-1.s4.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las adaptaciones aparecen por selección {{0}} a lo largo de muchas {{1}}.","banco":[{"id":"w1","texto":"natural"},{"id":"w2","texto":"generaciones"},{"id":"w3","texto":"artificial"},{"id":"w4","texto":"semanas"},{"id":"w5","texto":"horas"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Por eso los cambios muy rápidos del ambiente son tan peligrosos."}}]},{"slug":"animales-1.s5","orden":5,"tipo":"leccion","titulo_es":"Lo que la fauna hace por nosotros","bajada_es":"Polinizar, controlar plagas, limpiar y dispersar: el trabajo invisible de los animales.","minutos":12,"pasos":[{"slug":"animales-1.s5.p1","orden":1,"grupo":"animales-1.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Trabajo gratis","cuerpo":["Los animales prestan servicios que las personas necesitan: polinizan cultivos y plantas silvestres, controlan plagas, dispersan semillas que regeneran bosques, reciclan nutrientes y eliminan cadáveres. Si hubiera que reemplazar esos servicios con trabajo humano o máquinas, costaría fortunas, y muchas veces sería imposible."]},"solucion":{}},{"slug":"animales-1.s5.p2","orden":2,"grupo":"animales-1.s5.p2","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada animal con el servicio que presta.","izquierda":[{"id":"a1","texto":"Abejas nativas"},{"id":"a2","texto":"Murciélagos insectívoros"},{"id":"a3","texto":"Cóndor andino"},{"id":"a4","texto":"Zorzal"}],"derecha":[{"id":"b1","texto":"Polinizar flores y cultivos"},{"id":"b2","texto":"Comer insectos que pueden ser plagas"},{"id":"b3","texto":"Eliminar cadáveres de animales"},{"id":"b4","texto":"Dispersar semillas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro trabajos que hacen los animales sin cobrar."}},{"slug":"animales-1.s5.p3","orden":3,"grupo":"animales-1.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Murciélagos, lechuzas y plagas","cuerpo":["Un murciélago insectívoro puede comer cientos de insectos en una noche, incluidos mosquitos y polillas que dañan cultivos. Una familia de lechuzas del campanario puede cazar cientos o miles de roedores en un año. Por eso, en muchos campos se colocan cajas nido para lechuzas como control natural de roedores.","Matar murciélagos o lechuzas por miedo o superstición termina trayendo más plagas."]},"solucion":{}},{"slug":"animales-1.s5.p4","orden":4,"grupo":"animales-1.s5.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué matar lechuzas puede traer más ratas.","items":[{"id":"i1","texto":"Se matan las lechuzas de un campo"},{"id":"i2","texto":"Hay menos depredadores de roedores"},{"id":"i3","texto":"Los roedores se multiplican"},{"id":"i4","texto":"Aumentan los daños en los cultivos y los riesgos sanitarios"},{"id":"i5","texto":"Las lechuzas traen las ratas al campo"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un depredador natural es un control de plagas que trabaja todas las noches, gratis."}},{"slug":"animales-1.s5.p5","orden":5,"grupo":"animales-1.s5.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Los murciélagos son animales dañinos que conviene eliminar.","razones":[{"id":"r1","texto":"Porque controlan insectos y dispersan semillas"},{"id":"r2","texto":"Porque todos los murciélagos se alimentan de sangre"},{"id":"r3","texto":"Porque los murciélagos no comen nada"}]},"solucion":{"valor":false,"explicacion":"La mayoría de los murciélagos de Argentina come insectos o frutos: controlan plagas y dispersan semillas. No hay que tocarlos con las manos, pero tampoco eliminarlos.","clave":["r1"]}},{"slug":"animales-1.s5.p6","orden":6,"grupo":"animales-1.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Carroñeros: el servicio de limpieza","cuerpo":["Los carroñeros, como el cóndor andino, los jotes, los caranchos y muchos insectos, comen cadáveres de animales. Así evitan que los restos se pudran durante semanas y que se propaguen enfermedades.","El cóndor andino, una de las aves voladoras más grandes del mundo, con unos 3 metros de envergadura, está amenazado sobre todo por envenenamientos: comen cadáveres con cebos tóxicos que se ponen para matar a otros animales."]},"solucion":{}},{"slug":"animales-1.s5.p7","orden":7,"grupo":"animales-1.s5.p7","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un cebo envenenado mata cóndores.","items":[{"id":"i1","texto":"Se pone veneno en un cadáver para matar zorros o pumas"},{"id":"i2","texto":"Un grupo de cóndores come del cadáver"},{"id":"i3","texto":"Los cóndores se envenenan"},{"id":"i4","texto":"Mueren varios cóndores de una sola vez"},{"id":"i5","texto":"El veneno solo afecta a la especie buscada"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Los venenos no eligen: matan a todo lo que come del cebo. Por eso están prohibidos y son tan dañinos."}},{"slug":"animales-1.s5.p8","orden":8,"grupo":"animales-1.s5.p8","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué servicios prestan los carroñeros? Marcá todos.","opciones":[{"id":"o1","texto":"Eliminan cadáveres"},{"id":"o2","texto":"Reducen la propagación de enfermedades"},{"id":"o3","texto":"Reciclan nutrientes"},{"id":"o4","texto":"Polinizan flores"},{"id":"o5","texto":"Fabrican oxígeno"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Son el servicio de limpieza de la naturaleza. Sin ellos, los cadáveres duran mucho más y pueden contagiar enfermedades."}},{"slug":"animales-1.s5.p9","orden":9,"grupo":"animales-1.s5.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El valor de lo que no se ve","cuerpo":["Según la plataforma científica IPBES, alrededor de las tres cuartas partes de los tipos de cultivos alimentarios del mundo dependen, al menos en parte, de la polinización animal. Muchos de ellos son frutas, verduras y frutos secos que aportan vitaminas y minerales esenciales.","Casi nunca vemos estos servicios en acción, y por eso es fácil subestimarlos. Se notan cuando faltan."],"destacado":{"valor":"≈ 75 %","texto":"de los tipos de cultivos alimentarios del mundo dependen en parte de la polinización animal."}},"solucion":{}},{"slug":"animales-1.s5.p10","orden":10,"grupo":"animales-1.s5.p10","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de los tipos de cultivos alimentarios del mundo depende, al menos en parte, de polinizadores animales.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":75,"banda":"lineal","explicacion":"Alrededor de tres de cada cuatro. No todos dependen del mismo modo, pero sin polinizadores muchas frutas y verduras rendirían mucho menos."}},{"slug":"animales-1.s5.p11","orden":11,"grupo":"animales-1.s5.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué medida es mejor para controlar roedores en un campo a largo plazo?","opciones":[{"id":"o1","texto":"Instalar cajas nido para lechuzas"},{"id":"o2","texto":"Poner cebos envenenados por todo el campo"},{"id":"o3","texto":"Matar a los zorros y las lechuzas que hay"},{"id":"o4","texto":"Quemar los pastizales cercanos"}]},"solucion":{"clave":["o1"],"explicacion":"Aliarse con los depredadores naturales es barato, permanente y no envenena a otras especies.","por_opcion":{"o3":"Sacarías justamente a los depredadores que controlan a los roedores."}}},{"slug":"animales-1.s5.p12","orden":12,"grupo":"animales-1.s5.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Las lechuzas cazan muchos roedores."},{"id":"s2","texto":"Hay que matar a los murciélagos porque traen plagas."},{"id":"s3","texto":"El cóndor andino come cadáveres."},{"id":"s4","texto":"Poner veneno en un cadáver solo mata al zorro que se busca."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La fauna trabaja para nosotros. Atacarla suele salir caro.","por_opcion":{"s2":"Los murciélagos insectívoros comen insectos que pueden ser plagas.","s4":"Los cebos envenenados matan a todo lo que come de ellos, incluidos cóndores."}}},{"slug":"animales-1.s5.p13","orden":13,"grupo":"animales-1.s5.p13","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una colonia de 200 murciélagos insectívoros come en promedio 300 insectos por murciélago por noche. ¿Cuántos insectos come la colonia en una noche?","unidad":"insectos","decimales":0},"solucion":{"valor":60000,"tolerancia":1200,"explicacion":"200 × 300 = 60.000 insectos por noche. En un verano, decenas de millones: un control de plagas gratuito."}},{"slug":"animales-1.s5.p13.v2","orden":13,"grupo":"animales-1.s5.p13","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una colonia de 500 murciélagos insectívoros come en promedio 500 insectos por murciélago por noche. ¿Cuántos insectos come la colonia en una noche?","unidad":"insectos","decimales":0},"solucion":{"valor":250000,"tolerancia":5000,"explicacion":"500 × 500 = 250.000 insectos por noche. En un verano, decenas de millones: un control de plagas gratuito."}},{"slug":"animales-1.s5.p13.v3","orden":13,"grupo":"animales-1.s5.p13","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una colonia de 1.000 murciélagos insectívoros come en promedio 400 insectos por murciélago por noche. ¿Cuántos insectos come la colonia en una noche?","unidad":"insectos","decimales":0},"solucion":{"valor":400000,"tolerancia":8000,"explicacion":"1.000 × 400 = 400.000 insectos por noche. En un verano, decenas de millones: un control de plagas gratuito."}},{"slug":"animales-1.s5.p14","orden":14,"grupo":"animales-1.s5.p14","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá la envergadura (de punta a punta de las alas) de un cóndor andino adulto.","min":0.5,"max":6,"paso":0.1,"unidad":"m","escala":"lineal"},"solucion":{"valor":3,"banda":"lineal","explicacion":"Alrededor de 3 metros. Es una de las aves voladoras más grandes del mundo, y aprovecha las corrientes de aire para planear horas sin aletear."}},{"slug":"animales-1.s5.p15","orden":15,"grupo":"animales-1.s5.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los murciélagos y las lechuzas controlan {{0}}; los cóndores eliminan {{1}}; y las abejas {{2}} cultivos.","banco":[{"id":"w1","texto":"plagas"},{"id":"w2","texto":"cadáveres"},{"id":"w3","texto":"polinizan"},{"id":"w4","texto":"semillas"},{"id":"w5","texto":"nidos"},{"id":"w6","texto":"envenenan"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres servicios que la fauna presta gratis todos los días."}}]},{"slug":"animales-1.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: la trama de la vida","bajada_es":"Biodiversidad, redes tróficas, especies clave, adaptaciones y servicios, mezclados.","minutos":8,"pasos":[{"slug":"animales-1.s6.p1","orden":1,"grupo":"animales-1.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «La trama de la vida». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"animales-1.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la laguna de los Álamos","bajada_es":"En una laguna pampeana algo se desequilibró. Con los datos, encontrá la causa y proponé qué hacer.","minutos":10,"pasos":[{"slug":"animales-1.s7.p1","orden":1,"grupo":"animales-1.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La laguna","cuerpo":["Los vecinos de una laguna pampeana notan que el agua está cada vez más turbia y verde, y que casi no se ven tarariras. Desde hace tres años, un grupo pesca con redes todas las tarariras que encuentra para venderlas. Los pescadores deportivos cuentan que hay \"mojarras por todos lados\".","Un estudio de la universidad midió la cantidad de mojarras: se triplicó en tres años. El plancton que filtra el agua bajó a la mitad."]},"solucion":{}},{"slug":"animales-1.s7.p2","orden":2,"grupo":"animales-1.s7.p2","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena más probable de lo que pasó en la laguna.","items":[{"id":"i1","texto":"Se pescan casi todas las tarariras"},{"id":"i2","texto":"Las mojarras pierden a su principal depredador"},{"id":"i3","texto":"Las mojarras se triplican"},{"id":"i4","texto":"Comen mucho del plancton que filtra el agua"},{"id":"i5","texto":"Crecen las algas y el agua se pone turbia y verde"},{"id":"i6","texto":"Las tarariras enturbian el agua al desaparecer"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una cascada trófica: un cambio arriba de la red baja hasta el color del agua."}},{"slug":"animales-1.s7.p3","orden":3,"grupo":"animales-1.s7.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si había 2.000 mojarras por hectárea y la cantidad se triplicó, ¿cuántas hay ahora por hectárea?","unidad":"mojarras por hectárea","decimales":0},"solucion":{"valor":6000,"tolerancia":120,"explicacion":"2.000 × 3 = 6.000. Sin su depredador, la población crece hasta que otro factor la limita."}},{"slug":"animales-1.s7.p3.v2","orden":3,"grupo":"animales-1.s7.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si había 5.000 mojarras por hectárea y la cantidad se triplicó, ¿cuántas hay ahora por hectárea?","unidad":"mojarras por hectárea","decimales":0},"solucion":{"valor":15000,"tolerancia":300,"explicacion":"5.000 × 3 = 15.000. Sin su depredador, la población crece hasta que otro factor la limita."}},{"slug":"animales-1.s7.p3.v3","orden":3,"grupo":"animales-1.s7.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si había 1.500 mojarras por hectárea y la cantidad se triplicó, ¿cuántas hay ahora por hectárea?","unidad":"mojarras por hectárea","decimales":0},"solucion":{"valor":4500,"tolerancia":90,"explicacion":"1.500 × 3 = 4.500. Sin su depredador, la población crece hasta que otro factor la limita."}},{"slug":"animales-1.s7.p4","orden":4,"grupo":"animales-1.s7.p4","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es la medida más directa para empezar a recuperar la laguna?","opciones":[{"id":"o1","texto":"Regular la pesca de tarariras"},{"id":"o2","texto":"Echar productos químicos para matar las algas"},{"id":"o3","texto":"Pescar todas las mojarras con redes"},{"id":"o4","texto":"Traer peces exóticos para que coman mojarras"}]},"solucion":{"clave":["o1"],"explicacion":"Atacar la causa: devolverle a la red su depredador. Los químicos y los exóticos suelen traer problemas nuevos.","por_opcion":{"o3":"Ayudaría un tiempo, pero sin el depredador las mojarras vuelven a crecer."}}},{"slug":"animales-1.s7.p5","orden":5,"grupo":"animales-1.s7.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Traer un pez exótico para que coma mojarras es una buena solución.","razones":[{"id":"r1","texto":"Porque puede volverse invasor y causar nuevos daños"},{"id":"r2","texto":"Porque los peces exóticos no comen"},{"id":"r3","texto":"Porque las mojarras son exóticas"}]},"solucion":{"valor":false,"explicacion":"Un pez exótico puede volverse invasor y causar daños mayores. Mejor recuperar al depredador nativo, la tararira.","clave":["r1"]}},{"slug":"animales-1.s7.p6","orden":6,"grupo":"animales-1.s7.p6","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las propuestas de los vecinos.","grupos":[{"id":"g1","nombre":"Ayudan a recuperar la laguna"},{"id":"g2","nombre":"No ayudan o empeoran"}],"items":[{"id":"i1","texto":"Veda de pesca de tarariras por dos temporadas"},{"id":"i2","texto":"Echar alguicidas al agua"},{"id":"i3","texto":"Talla mínima para las tarariras que se pescan"},{"id":"i4","texto":"Soltar peces de acuario"},{"id":"i5","texto":"Controlar los vuelcos de fertilizantes de los campos cercanos"},{"id":"i6","texto":"Pescar más tarariras antes de que se prohíba"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las buenas medidas atacan la causa y cuidan la red. Las malas tapan síntomas o agregan problemas."}},{"slug":"animales-1.s7.p7","orden":7,"grupo":"animales-1.s7.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué datos conviene seguir midiendo para saber si la laguna se recupera? Marcá todos.","opciones":[{"id":"o1","texto":"Cantidad de tarariras"},{"id":"o2","texto":"Cantidad de mojarras"},{"id":"o3","texto":"Turbidez del agua"},{"id":"o4","texto":"Cantidad de plancton"},{"id":"o5","texto":"Cantidad de autos en la costanera"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Medir las piezas de la red permite ver si la cascada se revierte. Como en el tronco: medir antes y después."}},{"slug":"animales-1.s7.p8","orden":8,"grupo":"animales-1.s7.p8","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La municipalidad publica su plan. Marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Habrá veda de pesca de tarariras durante dos temporadas."},{"id":"s2","texto":"Como el problema son las algas, las mataremos con químicos y listo."},{"id":"s3","texto":"La universidad seguirá midiendo peces y plancton."},{"id":"s4","texto":"Soltaremos truchas para que coman mojarras."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan ataca la causa, respeta la red y mide los resultados.","por_opcion":{"s2":"Las algas son un síntoma; la causa es la falta de depredadores. Los químicos dañan toda la red.","s4":"Traer un pez exótico puede generar una invasión."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"animales-2","rama":"animales","orden":2,"nivel":1,"titulo_es":"Vecinos silvestres","bajada_es":"Horneros, comadrejas, murciélagos y carpinchos: cómo convivir con la fauna de la ciudad, qué hacer si encontrás un animal y cómo cuidar a las mascotas sin dañar a nadie.","objetivos_es":["Reconocer especies silvestres nativas y exóticas de las ciudades argentinas","Aplicar pautas de convivencia y actuar bien ante un animal silvestre","Evaluar el impacto de perros y gatos sobre la fauna","Explicar por qué no se liberan mascotas exóticas y qué es el tráfico de fauna","Proponer medidas para ciudades más amigables con la fauna"],"repasa":["animales-1","tronco-3"],"requiere_tronco":1,"fuentes":["protocolo-fauna-cba","red-centros-rescate","crfs-ecoparque","gcba-cinco-libertades","ley-22421-fauna","cites","conicet-carpinchos","loss-2013-gatos","loss-2014-vidrios","invasoras-mayds","aves-argentinas"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"animales-2.s1","orden":1,"tipo":"leccion","titulo_es":"Quién vive en la ciudad","bajada_es":"Aves, mamíferos, reptiles e insectos que comparten el barrio con nosotros, nativos y exóticos.","minutos":11,"pasos":[{"slug":"animales-2.s1.p1","orden":1,"grupo":"animales-2.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una ciudad llena de vida","cuerpo":["Las ciudades no son solo cemento: en plazas, jardines, terrenos baldíos, arroyos y hasta balcones viven muchas especies. En las ciudades argentinas son comunes aves nativas como el hornero —el ave nacional—, el benteveo, el zorzal colorado, la calandria, el chingolo, el tero y la paloma picazuró.","También hay mamíferos nativos que pasan desapercibidos, como la comadreja overa, un marsupial nocturno, y muchas especies de murciélagos. Y lagartijas, sapos, mariposas, abejas nativas y cientos de insectos."]},"solucion":{}},{"slug":"animales-2.s1.p2","orden":2,"grupo":"animales-2.s1.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos animales son nativos y comunes en ciudades argentinas? Marcá todos.","opciones":[{"id":"o1","texto":"Hornero"},{"id":"o2","texto":"Benteveo"},{"id":"o3","texto":"Comadreja overa"},{"id":"o4","texto":"Zorzal colorado"},{"id":"o5","texto":"Canguro"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Mucha fauna nativa vive entre nosotros. El canguro, claro, es de Australia."}},{"slug":"animales-2.s1.p3","orden":3,"grupo":"animales-2.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los que llegaron con nosotros","cuerpo":["Otras especies urbanas son exóticas, traídas por personas. El gorrión llegó de Europa en el siglo XIX; la paloma doméstica, también. El estornino pinto, un ave europea, se liberó en Buenos Aires hacia fines de los años ochenta y se expandió por buena parte del país, compitiendo con aves nativas por los huecos donde anidan.","Las ratas y los ratones domésticos también son exóticos y viajaron con las personas en barcos."]},"solucion":{}},{"slug":"animales-2.s1.p4","orden":4,"grupo":"animales-2.s1.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es nativa de Argentina o exótica?","grupos":[{"id":"g1","nombre":"Nativa"},{"id":"g2","nombre":"Exótica"}],"items":[{"id":"i1","texto":"Hornero"},{"id":"i2","texto":"Gorrión"},{"id":"i3","texto":"Paloma picazuró"},{"id":"i4","texto":"Paloma doméstica"},{"id":"i5","texto":"Tero"},{"id":"i6","texto":"Estornino pinto"},{"id":"i7","texto":"Comadreja overa"},{"id":"i8","texto":"Rata parda"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2","i7":"g1","i8":"g2"},"explicacion":"Que un animal sea común en la ciudad no dice si es nativo. Varias de las especies más vistas vinieron con las personas."}},{"slug":"animales-2.s1.p5","orden":5,"grupo":"animales-2.s1.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La comadreja overa es un animal peligroso que conviene eliminar de los jardines.","razones":[{"id":"r1","texto":"Porque es un marsupial nativo que ayuda a controlar plagas"},{"id":"r2","texto":"Porque la comadreja es una rata grande"},{"id":"r3","texto":"Porque la comadreja ataca a las personas para comer"}]},"solucion":{"valor":false,"explicacion":"Es un marsupial nativo, tímido, que come insectos, caracoles, frutos y hasta ratones. Ayuda a controlar plagas. Si se siente amenazada, se hace la muerta.","clave":["r1"]}},{"slug":"animales-2.s1.p6","orden":6,"grupo":"animales-2.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ciudades sobre humedales","cuerpo":["Muchas ciudades crecen sobre ambientes naturales, como humedales. Cuando en 2021 los carpinchos se hicieron famosos en un barrio cerrado del norte del conurbano, especialistas del CONICET recordaron que ese barrio se construyó sobre el humedal donde los carpinchos vivían desde siempre: no eran ellos los invasores.","La convivencia con fauna silvestre en la ciudad es, muchas veces, la consecuencia de haber ocupado su ambiente."]},"solucion":{}},{"slug":"animales-2.s1.p7","orden":7,"grupo":"animales-2.s1.p7","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué aparecieron tantos carpinchos en un barrio nuevo.","items":[{"id":"i1","texto":"Se construye un barrio sobre un humedal"},{"id":"i2","texto":"Los carpinchos pierden gran parte de su hábitat"},{"id":"i3","texto":"Quedan lagunas y céspedes con agua y pasto"},{"id":"i4","texto":"Los carpinchos siguen viviendo en lo que queda"},{"id":"i5","texto":"Aparecen conflictos con los vecinos"},{"id":"i6","texto":"Los carpinchos llegaron desde otro país"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Los carpinchos no invadieron el barrio: el barrio se construyó en su casa."}},{"slug":"animales-2.s1.p8","orden":8,"grupo":"animales-2.s1.p8","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada animal urbano con algo que lo caracteriza.","izquierda":[{"id":"a1","texto":"Hornero"},{"id":"a2","texto":"Tero"},{"id":"a3","texto":"Murciélago"},{"id":"a4","texto":"Comadreja overa"}],"derecha":[{"id":"b1","texto":"Construye su nido de barro"},{"id":"b2","texto":"Grita fuerte cuando alguien se acerca a su nido"},{"id":"b3","texto":"Caza insectos de noche"},{"id":"b4","texto":"Lleva a sus crías en una bolsa"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Conocer a los vecinos ayuda a entenderlos y a no temerles."}},{"slug":"animales-2.s1.p9","orden":9,"grupo":"animales-2.s1.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué el estornino pinto es un problema para aves nativas?","opciones":[{"id":"o1","texto":"Porque compite con ellas por los huecos para anidar"},{"id":"o2","texto":"Porque se come todas las semillas de los árboles"},{"id":"o3","texto":"Porque ataca a las personas en las plazas"},{"id":"o4","texto":"Porque destruye los nidos de hornero con el pico"}]},"solucion":{"clave":["o1"],"explicacion":"Muchas aves nativas anidan en huecos. Un competidor exótico abundante les quita lugar.","por_opcion":{"o3":"No es peligroso para las personas: el problema es su competencia con aves nativas."}}},{"slug":"animales-2.s1.p10","orden":10,"grupo":"animales-2.s1.p10","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario vecinal y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El hornero es el ave nacional."},{"id":"s2","texto":"Los gorriones son aves nativas de la pampa."},{"id":"s3","texto":"En la ciudad viven murciélagos."},{"id":"s4","texto":"Los carpinchos invadieron el barrio desde afuera."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Saber quién es quién cambia cómo miramos los conflictos con la fauna.","por_opcion":{"s2":"Son exóticos: llegaron de Europa en el siglo XIX.","s4":"El barrio se construyó sobre el humedal donde ya vivían."}}},{"slug":"animales-2.s1.p11","orden":11,"grupo":"animales-2.s1.p11","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La cotorra, tan común en las ciudades, es una especie exótica en Argentina.","razones":[{"id":"r1","texto":"Porque es nativa de la región, aunque sea invasora en otros países"},{"id":"r2","texto":"Porque llegó de Europa con los barcos"},{"id":"r3","texto":"Porque es un ave de Australia"}]},"solucion":{"valor":false,"explicacion":"Es nativa de Argentina y la región. Se volvió muy abundante en ciudades y cultivos, y en otros países, como España, sí es una invasora.","clave":["r1"]}},{"slug":"animales-2.s1.p12","orden":12,"grupo":"animales-2.s1.p12","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿En qué lugares de una ciudad puede vivir fauna silvestre? Marcá todos.","opciones":[{"id":"o1","texto":"Plazas con árboles"},{"id":"o2","texto":"Arroyos y sus orillas"},{"id":"o3","texto":"Balcones con plantas"},{"id":"o4","texto":"Terrenos baldíos con vegetación"},{"id":"o5","texto":"Solo en zoológicos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La fauna urbana aprovecha cualquier rincón con agua, refugio y comida."}},{"slug":"animales-2.s1.p13","orden":13,"grupo":"animales-2.s1.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El {{0}} es el ave nacional; el gorrión y la paloma doméstica son {{1}}; y la comadreja overa es un {{2}} nativo.","banco":[{"id":"w1","texto":"hornero"},{"id":"w2","texto":"exóticos"},{"id":"w3","texto":"marsupial"},{"id":"w4","texto":"cóndor"},{"id":"w5","texto":"nativos"},{"id":"w6","texto":"roedor"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres vecinos del barrio, bien presentados."}},{"slug":"animales-2.s1.p14","orden":14,"grupo":"animales-2.s1.p14","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos lugares de la ciudad según cuánta fauna silvestre suelen albergar, de más a menos.","items":[{"id":"i1","texto":"Reserva ecológica con humedal"},{"id":"i2","texto":"Plaza grande con árboles y arbustos nativos"},{"id":"i3","texto":"Vereda arbolada"},{"id":"i4","texto":"Estacionamiento de cemento"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Más hábitat natural, más fauna. Pero hasta una vereda con árboles hace una diferencia.","valores":{"i1":"mucha","i2":"bastante","i3":"poca","i4":"casi nada"}}}]},{"slug":"animales-2.s2","orden":2,"tipo":"leccion","titulo_es":"Convivir sin dañar","bajada_es":"No alimentar, no capturar, no molestar, y qué hacer si encontrás un pichón o un animal herido.","minutos":11,"pasos":[{"slug":"animales-2.s2.p1","orden":1,"grupo":"animales-2.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las reglas básicas","cuerpo":["Convivir con la fauna silvestre tiene reglas simples: no alimentarla (se vuelve dependiente, pierde el miedo y puede enfermar con comida humana), no capturarla ni tenerla como mascota, no molestarla en sus nidos o refugios y mantener a perros y gatos controlados.","La fauna silvestre está protegida por ley: la Ley 22.421 de conservación de la fauna silvestre prohíbe cazarla, capturarla o comerciarla sin autorización."]},"solucion":{}},{"slug":"animales-2.s2.p2","orden":2,"grupo":"animales-2.s2.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conviene hacer para convivir con la fauna silvestre? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"Observarla a distancia"},{"id":"o2","texto":"No darle comida"},{"id":"o3","texto":"Mantener a perros y gatos controlados"},{"id":"o4","texto":"No tocar nidos ni crías"},{"id":"o5","texto":"Llevarse un pichón a casa para criarlo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La fauna silvestre está mejor en libertad, sin depender de las personas."}},{"slug":"animales-2.s2.p3","orden":3,"grupo":"animales-2.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué no alimentar","cuerpo":["Darles comida a animales silvestres parece un gesto amable, pero trae problemas: pierden el miedo a las personas y pueden volverse agresivos o terminar atropellados; se concentran muchos en un lugar y se contagian enfermedades; y la comida humana, como el pan, les hace mal.","En varias ciudades, los carpinchos o los zorros alimentados por la gente terminaron en conflictos que los perjudicaron a ellos."]},"solucion":{}},{"slug":"animales-2.s2.p4","orden":4,"grupo":"animales-2.s2.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué alimentar a un zorro puede terminar mal para él.","items":[{"id":"i1","texto":"Personas alimentan a un zorro en una ruta"},{"id":"i2","texto":"El zorro pierde el miedo y se acerca a los autos"},{"id":"i3","texto":"Espera comida al costado de la ruta"},{"id":"i4","texto":"Aumenta el riesgo de que lo atropellen"},{"id":"i5","texto":"El zorro aprende a cruzar la ruta sin peligro"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Lo que parece amabilidad puede convertirse en una trampa. En parques nacionales, alimentar fauna está prohibido."}},{"slug":"animales-2.s2.p5","orden":5,"grupo":"animales-2.s2.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Darles pan a los patos de una laguna es bueno para ellos.","razones":[{"id":"r1","texto":"Porque el pan no es su alimento y puede enfermarlos"},{"id":"r2","texto":"Porque los patos no comen nada"},{"id":"r3","texto":"Porque el pan purifica el agua de la laguna"}]},"solucion":{"valor":false,"explicacion":"El pan no les aporta lo que necesitan y puede enfermarlos; además, el pan que sobra se pudre en el agua. Mejor observarlos sin alimentar.","clave":["r1"]}},{"slug":"animales-2.s2.p6","orden":6,"grupo":"animales-2.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El pichón en el suelo","cuerpo":["En primavera, es común encontrar un pichón de ave en el suelo. Muchas veces es un volantón: un pichón con plumas que está aprendiendo a volar y cuyos padres siguen cerca alimentándolo. En ese caso, lo mejor es dejarlo tranquilo, alejar a perros y gatos y observar de lejos.","Si es un pichón sin plumas o casi sin plumas, que se cayó del nido, se puede intentar devolverlo al nido si se lo ve. Si está herido o en peligro, conviene comunicarse con un centro de rescate de fauna o la autoridad ambiental. Nunca hay que darle agua ni comida por la boca: puede ahogarse."]},"solucion":{}},{"slug":"animales-2.s2.p7","orden":7,"grupo":"animales-2.s2.p7","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená qué hacer si encontrás un pichón con plumas en el suelo.","items":[{"id":"i1","texto":"Observar de lejos si los padres están cerca"},{"id":"i2","texto":"Alejar a perros y gatos"},{"id":"i3","texto":"Dejarlo en el lugar si no corre peligro"},{"id":"i4","texto":"Si está herido, contactar a un centro de rescate"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La mayoría de los volantones no necesitan ayuda: sus padres los siguen cuidando."}},{"slug":"animales-2.s2.p8","orden":8,"grupo":"animales-2.s2.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué conviene hacer en cada caso?","grupos":[{"id":"g1","nombre":"Dejarlo donde está y observar"},{"id":"g2","nombre":"Contactar a un centro de rescate o la autoridad"}],"items":[{"id":"i1","texto":"Pichón con plumas saltando en el pasto"},{"id":"i2","texto":"Lechuza con un ala rota"},{"id":"i3","texto":"Tero defendiendo su nido en un parque"},{"id":"i4","texto":"Tortuga atropellada en la ruta"},{"id":"i5","texto":"Zorro enredado en un alambre"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Un animal sano en su ambiente no necesita rescate. Uno herido sí, pero con especialistas."}},{"slug":"animales-2.s2.p9","orden":9,"grupo":"animales-2.s2.p9","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Encontraste un pichón sin plumas debajo de un árbol y ves el nido. ¿Qué hacés?","opciones":[{"id":"o1","texto":"Intentar devolverlo al nido con cuidado"},{"id":"o2","texto":"Llevarlo a casa y darle leche con una jeringa"},{"id":"o3","texto":"Darle agua por el pico para que se hidrate"},{"id":"o4","texto":"Dejarlo al sol para que se caliente"}]},"solucion":{"clave":["o1"],"explicacion":"Si el nido está a mano, devolverlo es lo mejor. Que lo toques no hace que los padres lo rechacen: esa es una creencia falsa.","por_opcion":{"o3":"Nunca se da agua ni comida por la boca: puede ahogarse."}}},{"slug":"animales-2.s2.p10","orden":10,"grupo":"animales-2.s2.p10","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si tocás un pichón, sus padres lo van a rechazar por el olor.","razones":[{"id":"r1","texto":"Porque la mayoría de las aves no rechaza a sus crías por el olor"},{"id":"r2","texto":"Porque las aves no tienen crías"},{"id":"r3","texto":"Porque los pichones no tienen olor"}]},"solucion":{"valor":false,"explicacion":"Es una creencia muy extendida pero falsa para la mayoría de las aves: no rechazan a sus crías por el olor humano. Se puede devolver un pichón al nido.","clave":["r1"]}},{"slug":"animales-2.s2.p11","orden":11,"grupo":"animales-2.s2.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada situación con quién conviene contactar.","izquierda":[{"id":"a1","texto":"Animal silvestre herido"},{"id":"a2","texto":"Venta de aves silvestres en una feria"},{"id":"a3","texto":"Serpiente dentro de una casa"},{"id":"a4","texto":"Carpinchos en el barrio"}],"derecha":[{"id":"b1","texto":"Centro de rescate de fauna o autoridad ambiental"},{"id":"b2","texto":"Autoridad de fauna para denunciar"},{"id":"b3","texto":"Bomberos o la autoridad ambiental local"},{"id":"b4","texto":"Nadie: observarlos a distancia"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Saber a quién llamar evita que las personas actúen solas y dañen al animal o se lastimen."}},{"slug":"animales-2.s2.p12","orden":12,"grupo":"animales-2.s2.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos de un grupo de vecinos y marcá los equivocados.","segmentos":[{"id":"s1","texto":"Si encontrás un volantón, alejá al gato y observá."},{"id":"s2","texto":"Si encontrás un pichón, dale leche con una jeringa."},{"id":"s3","texto":"No alimentes a los carpinchos."},{"id":"s4","texto":"Si ves una comadreja, espantala o matala porque es peligrosa."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La buena voluntad necesita buena información.","por_opcion":{"s2":"Nunca se da nada por la boca, y la leche les hace mal.","s4":"Es un marsupial nativo inofensivo que ayuda a controlar plagas."}}},{"slug":"animales-2.s2.p13","orden":13,"grupo":"animales-2.s2.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"A la fauna silvestre no hay que {{0}} ni capturarla; la Ley {{1}} la protege; y ante un animal herido hay que llamar a un centro de {{2}}.","banco":[{"id":"w1","texto":"alimentarla"},{"id":"w2","texto":"22.421"},{"id":"w3","texto":"rescate"},{"id":"w4","texto":"fotografiarla"},{"id":"w5","texto":"25.675"},{"id":"w6","texto":"compras"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres reglas para convivir con la fauna sin dañarla."}}]},{"slug":"animales-2.s3","orden":3,"tipo":"leccion","titulo_es":"Mascotas y fauna","bajada_es":"Gatos que cazan, perros sueltos y la tenencia responsable: cómo cuidar a las mascotas sin dañar a la fauna.","minutos":11,"pasos":[{"slug":"animales-2.s3.p1","orden":1,"grupo":"animales-2.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las cinco libertades","cuerpo":["Tener una mascota es una responsabilidad. El bienestar animal se suele resumir en cinco libertades: que viva libre de hambre y sed; libre de incomodidad; libre de dolor, lesiones y enfermedades; libre para expresar su comportamiento normal; y libre de miedo y angustia.","La tenencia responsable también incluye la vacunación, la castración para evitar camadas no deseadas y el control para que la mascota no dañe a otras personas ni a la fauna."]},"solucion":{}},{"slug":"animales-2.s3.p2","orden":2,"grupo":"animales-2.s3.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estas son parte de las cinco libertades del bienestar animal? Marcá todas.","opciones":[{"id":"o1","texto":"Libre de hambre y sed"},{"id":"o2","texto":"Libre de dolor, lesiones y enfermedades"},{"id":"o3","texto":"Libre para expresar su comportamiento normal"},{"id":"o4","texto":"Libre de miedo y angustia"},{"id":"o5","texto":"Libre de tener que ir al veterinario"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Ir al veterinario es justamente parte de mantenerla libre de dolor y enfermedades."}},{"slug":"animales-2.s3.p3","orden":3,"grupo":"animales-2.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los gatos, cazadores","cuerpo":["Los gatos domésticos son cazadores eficientes, aunque estén bien alimentados. Un estudio publicado en Nature Communications estimó que en Estados Unidos los gatos que andan sueltos matan entre 1.300 y 4.000 millones de aves por año, además de muchísimos pequeños mamíferos. En islas, los gatos contribuyeron a la extinción de varias especies.","Tener el gato adentro, sobre todo al amanecer y al atardecer, o en un patio cerrado, reduce mucho su impacto sobre la fauna y también lo protege de accidentes y enfermedades."],"destacado":{"valor":"1.300-4.000 millones","texto":"de aves por año matarían los gatos sueltos en Estados Unidos, según un estudio de 2013."}},"solucion":{}},{"slug":"animales-2.s3.p4","orden":4,"grupo":"animales-2.s3.p4","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un gato bien alimentado no caza.","razones":[{"id":"r1","texto":"Porque cazar es un instinto que no depende del hambre"},{"id":"r2","texto":"Porque los gatos solo comen alimento balanceado"},{"id":"r3","texto":"Porque los gatos no pueden atrapar aves"}]},"solucion":{"valor":false,"explicacion":"La caza es un instinto independiente del hambre. Un gato bien alimentado puede cazar aves y otros animales igual.","clave":["r1"]}},{"slug":"animales-2.s3.p5","orden":5,"grupo":"animales-2.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un barrio hay 1.000 gatos que salen a la calle y cada uno caza en promedio 10 aves por año. ¿Cuántas aves cazan en total por año?","unidad":"aves","decimales":0},"solucion":{"valor":10000,"tolerancia":200,"explicacion":"1.000 × 10 = 10.000 aves por año. Poco por gato, mucho por barrio: la misma lógica del stand-by o de la basura."}},{"slug":"animales-2.s3.p5.v2","orden":5,"grupo":"animales-2.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un barrio hay 5.000 gatos que salen a la calle y cada uno caza en promedio 8 aves por año. ¿Cuántas aves cazan en total por año?","unidad":"aves","decimales":0},"solucion":{"valor":40000,"tolerancia":800,"explicacion":"5.000 × 8 = 40.000 aves por año. Poco por gato, mucho por barrio: la misma lógica del stand-by o de la basura."}},{"slug":"animales-2.s3.p5.v3","orden":5,"grupo":"animales-2.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un barrio hay 200 gatos que salen a la calle y cada uno caza en promedio 15 aves por año. ¿Cuántas aves cazan en total por año?","unidad":"aves","decimales":0},"solucion":{"valor":3000,"tolerancia":60,"explicacion":"200 × 15 = 3.000 aves por año. Poco por gato, mucho por barrio: la misma lógica del stand-by o de la basura."}},{"slug":"animales-2.s3.p6","orden":6,"grupo":"animales-2.s3.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un gato suelto afecta a las aves del barrio.","items":[{"id":"i1","texto":"Un gato sale libremente al jardín y la plaza"},{"id":"i2","texto":"Caza pichones y aves adultas"},{"id":"i3","texto":"Menos aves llegan a reproducirse"},{"id":"i4","texto":"Baja la población de aves del barrio"},{"id":"i5","texto":"El gato ahuyenta a las aves hacia lugares mejores"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un efecto chico multiplicado por muchos gatos y muchos años."}},{"slug":"animales-2.s3.p7","orden":7,"grupo":"animales-2.s3.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Perros sueltos","cuerpo":["Los perros sueltos o en jauría también afectan a la fauna: persiguen y matan aves que anidan en el suelo, como teros, ñandúes o pingüinos en la costa patagónica, atacan a ciervos, zorros o vizcachas, y transmiten enfermedades a animales silvestres.","En áreas naturales, reservas y playas con fauna, los perros tienen que ir con correa, y en muchos parques nacionales no están permitidos."]},"solucion":{}},{"slug":"animales-2.s3.p8","orden":8,"grupo":"animales-2.s3.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta práctica protege a la fauna o la pone en riesgo?","grupos":[{"id":"g1","nombre":"Protege a la fauna"},{"id":"g2","nombre":"La pone en riesgo"}],"items":[{"id":"i1","texto":"Llevar al perro con correa en la reserva"},{"id":"i2","texto":"Soltar al perro en una playa con colonia de aves"},{"id":"i3","texto":"Castrar a perros y gatos"},{"id":"i4","texto":"Abandonar camadas en un terreno baldío"},{"id":"i5","texto":"Tener al gato adentro de noche"},{"id":"i6","texto":"Dejar comida para gatos en una plaza con aves"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La tenencia responsable cuida a la mascota y a la fauna al mismo tiempo."}},{"slug":"animales-2.s3.p9","orden":9,"grupo":"animales-2.s3.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la castración de perros y gatos ayuda a la fauna silvestre?","opciones":[{"id":"o1","texto":"Porque evita camadas que terminan sueltas"},{"id":"o2","texto":"Porque los animales castrados no pueden correr"},{"id":"o3","texto":"Porque los castrados dejan de tener instinto de caza"},{"id":"o4","texto":"Porque así se vuelven animales silvestres"}]},"solucion":{"clave":["o1"],"explicacion":"Menos camadas no deseadas, menos animales abandonados y menos presión sobre la fauna.","por_opcion":{"o3":"El instinto de caza puede seguir; lo que se evita es la sobrepoblación de animales sueltos."}}},{"slug":"animales-2.s3.p10","orden":10,"grupo":"animales-2.s3.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada práctica de tenencia responsable con su beneficio.","izquierda":[{"id":"a1","texto":"Vacunar"},{"id":"a2","texto":"Castrar"},{"id":"a3","texto":"Correa en áreas naturales"},{"id":"a4","texto":"Gato adentro de noche"}],"derecha":[{"id":"b1","texto":"Evitar enfermedades que pueden pasar a la fauna"},{"id":"b2","texto":"Evitar camadas no deseadas"},{"id":"b3","texto":"Evitar persecuciones de fauna"},{"id":"b4","texto":"Reducir la caza de aves"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada práctica protege a la mascota, a las personas y a la fauna."}},{"slug":"animales-2.s3.p11","orden":11,"grupo":"animales-2.s3.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los gatos pueden cazar aunque estén bien alimentados."},{"id":"s2","texto":"Los perros sueltos no molestan a la fauna porque son domésticos."},{"id":"s3","texto":"Castrar evita camadas no deseadas."},{"id":"s4","texto":"Soltar al perro en una playa con aves es inofensivo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Querer a las mascotas incluye evitar que dañen a otros animales.","por_opcion":{"s2":"Los perros sueltos persiguen y matan fauna silvestre.","s4":"Puede perseguir aves que anidan y destruir nidos."}}},{"slug":"animales-2.s3.p12","orden":12,"grupo":"animales-2.s3.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los gatos cazan aunque estén bien {{0}}; en reservas, los perros van con {{1}}; y la {{2}} evita camadas no deseadas.","banco":[{"id":"w1","texto":"alimentados"},{"id":"w2","texto":"correa"},{"id":"w3","texto":"castración"},{"id":"w4","texto":"vacunados"},{"id":"w5","texto":"bozal"},{"id":"w6","texto":"vacuna"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas de tenencia responsable pensando en la fauna."}},{"slug":"animales-2.s3.p13","orden":13,"grupo":"animales-2.s3.p13","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas medidas por cuánto reducen la caza de aves por parte de un gato, de más a menos.","items":[{"id":"i1","texto":"Tenerlo siempre adentro o en patio cerrado"},{"id":"i2","texto":"Tenerlo adentro al amanecer, al atardecer y de noche"},{"id":"i3","texto":"Ponerle un collar con cascabel"},{"id":"i4","texto":"Dejarlo salir cuando quiera"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las horas de luz baja son las de mayor actividad de las aves y de caza del gato.","valores":{"i1":"casi la elimina","i2":"la reduce mucho","i3":"la reduce algo","i4":"no la reduce"}}}]},{"slug":"animales-2.s4","orden":4,"tipo":"leccion","titulo_es":"Nunca liberar, nunca comprar","bajada_es":"Tortugas de orejas rojas, peces de acuario y cardenales en jaulas: mascotas exóticas liberadas y tráfico de fauna.","minutos":11,"pasos":[{"slug":"animales-2.s4.p1","orden":1,"grupo":"animales-2.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Liberar una mascota exótica","cuerpo":["Cuando alguien se cansa de una mascota exótica —una tortuga, un pez, un reptil— y la suelta en una laguna o un parque, puede crear una invasión. La tortuga de orejas rojas, originaria de América del Norte y muy vendida como mascota, fue liberada en lagunas y arroyos de Argentina y figura en la lista oficial de especies exóticas invasoras: compite con las tortugas nativas y puede transmitirles enfermedades.","Lo mismo pasa con peces de acuario, plantas acuáticas y otros animales. Una mascota exótica nunca se libera: se busca otro hogar o se consulta con la autoridad ambiental."]},"solucion":{}},{"slug":"animales-2.s4.p2","orden":2,"grupo":"animales-2.s4.p2","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Soltar una tortuga de acuario en una laguna es una forma de devolverla a la naturaleza.","razones":[{"id":"r1","texto":"Porque no es su ambiente y puede volverse invasora"},{"id":"r2","texto":"Porque las tortugas no pueden nadar"},{"id":"r3","texto":"Porque las lagunas no tienen agua suficiente"}]},"solucion":{"valor":false,"explicacion":"No es su naturaleza: es de otro continente. Puede morir o volverse invasora y dañar a las especies nativas. Nunca se liberan mascotas exóticas.","clave":["r1"]}},{"slug":"animales-2.s4.p3","orden":3,"grupo":"animales-2.s4.p3","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una mascota liberada puede volverse invasora.","items":[{"id":"i1","texto":"Una familia suelta sus tortugas de orejas rojas en una laguna"},{"id":"i2","texto":"Las tortugas sobreviven y se reproducen"},{"id":"i3","texto":"Compiten con las tortugas nativas por comida y lugares para asolearse"},{"id":"i4","texto":"Las tortugas nativas disminuyen"},{"id":"i5","texto":"Las tortugas nativas se convierten en tortugas de orejas rojas"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un acto que parece bondadoso termina dañando a especies que no tienen nada que ver."}},{"slug":"animales-2.s4.p4","orden":4,"grupo":"animales-2.s4.p4","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Ya no podés cuidar a tu tortuga de acuario. ¿Qué es lo correcto?","opciones":[{"id":"o1","texto":"Buscarle otro hogar o consultar a la autoridad ambiental"},{"id":"o2","texto":"Soltarla en la laguna del parque más cercano"},{"id":"o3","texto":"Dejarla en la plaza para que alguien la encuentre"},{"id":"o4","texto":"Tirarla por el inodoro"}]},"solucion":{"clave":["o1"],"explicacion":"Una mascota exótica es responsabilidad de por vida. Si no se puede cuidar, se busca un hogar, nunca un río.","por_opcion":{"o3":"También es liberarla: puede morir o volverse invasora."}}},{"slug":"animales-2.s4.p5","orden":5,"grupo":"animales-2.s4.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El tráfico de fauna silvestre","cuerpo":["El tráfico de fauna es la captura, el transporte y la venta ilegal de animales silvestres, vivos o de sus partes. En Argentina, muchas aves —como el cardenal amarillo, el loro hablador o distintos jilgueros— se capturan en el campo para venderlas como mascotas en jaulas.","El cardenal amarillo está en peligro de extinción, y la captura para el comercio de aves de jaula es una de sus principales amenazas. Por cada ave que llega viva a una casa, muchas mueren en la captura y el transporte."]},"solucion":{}},{"slug":"animales-2.s4.p6","orden":6,"grupo":"animales-2.s4.p6","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué problemas causa el tráfico de fauna? Marcá todos.","opciones":[{"id":"o1","texto":"Lleva especies al borde de la extinción"},{"id":"o2","texto":"Muchos animales mueren en la captura y el transporte"},{"id":"o3","texto":"Puede transmitir enfermedades"},{"id":"o4","texto":"Alimenta redes delictivas"},{"id":"o5","texto":"Ayuda a conservar las especies en las casas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Las especies no se conservan en jaulas: se conservan en su ambiente."}},{"slug":"animales-2.s4.p7","orden":7,"grupo":"animales-2.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La ley y los acuerdos","cuerpo":["En Argentina, la Ley 22.421 protege a la fauna silvestre y prohíbe su caza, captura y comercio sin autorización. A nivel internacional, la convención CITES regula el comercio entre países de especies amenazadas.","La forma más efectiva de frenar el tráfico es no comprar animales silvestres y denunciar su venta ante la autoridad de fauna."]},"solucion":{}},{"slug":"animales-2.s4.p8","orden":8,"grupo":"animales-2.s4.p8","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada herramienta con lo que hace.","izquierda":[{"id":"a1","texto":"Ley 22.421"},{"id":"a2","texto":"CITES"},{"id":"a3","texto":"Denuncia ciudadana"},{"id":"a4","texto":"No comprar"}],"derecha":[{"id":"b1","texto":"Protege a la fauna silvestre en Argentina"},{"id":"b2","texto":"Regula el comercio internacional de especies amenazadas"},{"id":"b3","texto":"Avisa a la autoridad sobre ventas ilegales"},{"id":"b4","texto":"Quita la demanda que sostiene el tráfico"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Leyes, acuerdos y decisiones individuales. El tráfico existe porque alguien compra."}},{"slug":"animales-2.s4.p9","orden":9,"grupo":"animales-2.s4.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué comprar un cardenal en una feria alimenta su extinción.","items":[{"id":"i1","texto":"Alguien compra un cardenal amarillo en una feria"},{"id":"i2","texto":"El vendedor gana dinero con esa venta"},{"id":"i3","texto":"Vuelve a capturar más cardenales en el campo"},{"id":"i4","texto":"La población silvestre sigue bajando"},{"id":"i5","texto":"Comprarlo lo salva de estar en el campo"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La demanda es el motor del tráfico. Sin compradores, no hay negocio."}},{"slug":"animales-2.s4.p10","orden":10,"grupo":"animales-2.s4.p10","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es legal o es tráfico de fauna?","grupos":[{"id":"g1","nombre":"Legal"},{"id":"g2","nombre":"Tráfico o ilegal"}],"items":[{"id":"i1","texto":"Observar aves con binoculares"},{"id":"i2","texto":"Comprar un loro sacado del monte"},{"id":"i3","texto":"Adoptar un perro de un refugio"},{"id":"i4","texto":"Vender cardenales en una feria"},{"id":"i5","texto":"Fotografiar un zorro en un parque nacional"},{"id":"i6","texto":"Tener un tatú capturado como mascota"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La fauna silvestre no es mascota. Observarla y fotografiarla, en cambio, es libre y no le hace daño."}},{"slug":"animales-2.s4.p11","orden":11,"grupo":"animales-2.s4.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este aviso en redes y marcá lo problemático.","segmentos":[{"id":"s1","texto":"Vendo cardenal amarillo, cantor, sacado del campo."},{"id":"s2","texto":"Doy en adopción gatito castrado y vacunado."},{"id":"s3","texto":"Regalo tortuga de orejas rojas; si nadie la quiere, la suelto en el lago."},{"id":"s4","texto":"Busco hogar para perro adulto."}]},"solucion":{"clave":["s1","s3"],"explicacion":"Algunos avisos parecen inofensivos y no lo son.","por_opcion":{"s1":"Es tráfico de una especie en peligro de extinción: se debe denunciar.","s3":"Liberarla puede crear una invasión: nunca se liberan mascotas exóticas."}}},{"slug":"animales-2.s4.p12","orden":12,"grupo":"animales-2.s4.p12","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Una mascota exótica nunca se {{0}}; el comercio internacional de especies amenazadas lo regula {{1}}; y el tráfico existe porque alguien {{2}}.","banco":[{"id":"w1","texto":"libera"},{"id":"w2","texto":"CITES"},{"id":"w3","texto":"compra"},{"id":"w4","texto":"vacuna"},{"id":"w5","texto":"FIFA"},{"id":"w6","texto":"observa"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para no ser parte del problema."}},{"slug":"animales-2.s4.p13","orden":13,"grupo":"animales-2.s4.p13","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá en qué año aproximado se liberó el estornino pinto en Buenos Aires.","min":1900,"max":2020,"paso":1,"unidad":"año","escala":"lineal"},"solucion":{"valor":1987,"banda":"lineal","explicacion":"A fines de los años ochenta. En pocas décadas se expandió por buena parte del país: así de rápido puede avanzar una especie liberada."}}]},{"slug":"animales-2.s5","orden":5,"tipo":"leccion","titulo_es":"Una ciudad amiga de la fauna","bajada_es":"Vidrios, luces, agua y refugios: cambios chicos en casas y edificios que salvan muchos animales.","minutos":11,"pasos":[{"slug":"animales-2.s5.p1","orden":1,"grupo":"animales-2.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Vidrios que matan","cuerpo":["Las aves no ven los vidrios: ven el reflejo del cielo o de los árboles, o ven a través, y chocan. Un estudio publicado en la revista The Condor estimó que en Estados Unidos mueren entre 365 y 988 millones de aves por año por choques contra vidrios, la mayoría en casas y edificios bajos.","Se puede evitar con marcas visibles en el vidrio (puntos o líneas separados unos 5 a 10 centímetros), cortinas o mosquiteros exteriores, o vidrios especiales en edificios nuevos."],"destacado":{"valor":"365-988 millones","texto":"de aves mueren por año en Estados Unidos por chocar contra vidrios, según un estudio de 2014."}},"solucion":{}},{"slug":"animales-2.s5.p2","orden":2,"grupo":"animales-2.s5.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué las aves chocan contra los vidrios?","opciones":[{"id":"o1","texto":"Porque ven el reflejo del cielo o ven a través"},{"id":"o2","texto":"Porque les gusta golpear las ventanas"},{"id":"o3","texto":"Porque son aves enfermas que no ven bien"},{"id":"o4","texto":"Porque buscan comida adentro de las casas"}]},"solucion":{"clave":["o1"],"explicacion":"Para un ave, un vidrio reflectante es un pedazo de cielo o de árbol.","por_opcion":{"o3":"Aves sanas chocan igual: el vidrio es invisible para ellas."}}},{"slug":"animales-2.s5.p3","orden":3,"grupo":"animales-2.s5.p3","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué medidas reducen los choques de aves contra vidrios? Marcá todas.","opciones":[{"id":"o1","texto":"Marcas visibles separadas pocos centímetros"},{"id":"o2","texto":"Mosquiteros exteriores"},{"id":"o3","texto":"Cortinas o persianas"},{"id":"o4","texto":"Vidrios especiales en edificios nuevos"},{"id":"o5","texto":"Una sola calcomanía chica en el medio del ventanal"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Una silueta aislada no alcanza: el ave pasa por el costado. Hacen falta marcas repartidas en todo el vidrio."}},{"slug":"animales-2.s5.p4","orden":4,"grupo":"animales-2.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La noche iluminada","cuerpo":["La luz artificial de noche desorienta a muchos animales: aves migratorias que vuelan de noche, insectos que giran alrededor de las lámparas hasta morir, tortugas marinas recién nacidas que van hacia las luces en vez de hacia el mar. También afecta a murciélagos y ranas.","Apagar luces que no se usan, apuntar las luces hacia abajo y usar luces más cálidas (menos azules) reduce ese impacto, y además ahorra energía."]},"solucion":{}},{"slug":"animales-2.s5.p5","orden":5,"grupo":"animales-2.s5.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una luz exterior toda la noche afecta a los insectos.","items":[{"id":"i1","texto":"Se deja una luz blanca encendida toda la noche"},{"id":"i2","texto":"Miles de insectos nocturnos son atraídos"},{"id":"i3","texto":"Giran alrededor hasta agotarse o ser comidos"},{"id":"i4","texto":"Hay menos insectos para polinizar y alimentar a otros animales"},{"id":"i5","texto":"Los insectos aprenden a usar la luz para ver mejor"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La contaminación lumínica es una amenaza silenciosa para los insectos, que ya vienen en declive."}},{"slug":"animales-2.s5.p6","orden":6,"grupo":"animales-2.s5.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta iluminación es amigable con la fauna o no?","grupos":[{"id":"g1","nombre":"Más amigable"},{"id":"g2","nombre":"Menos amigable"}],"items":[{"id":"i1","texto":"Luz que apunta hacia abajo"},{"id":"i2","texto":"Reflector blanco apuntando al cielo"},{"id":"i3","texto":"Luz cálida con sensor de movimiento"},{"id":"i4","texto":"Luces de jardín encendidas toda la noche"},{"id":"i5","texto":"Apagar las luces del jardín a la noche"},{"id":"i6","texto":"Carteles luminosos en zonas naturales"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Menos luz, hacia abajo, cálida y solo cuando hace falta: la regla para la fauna y para la factura."}},{"slug":"animales-2.s5.p7","orden":7,"grupo":"animales-2.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Agua, refugios y comida natural","cuerpo":["En la ciudad, la fauna necesita agua, lugares para refugiarse y alimento natural. Un recipiente bajo con agua limpia (que se cambia seguido para que no críe mosquitos), arbustos densos, troncos, piedras, plantas nativas con flores y frutos y cajas nido para aves o murciélagos crean hábitat.","También ayuda dejar un rincón del jardín menos \"prolijo\", con hojas secas y pasto más alto, donde se refugian insectos, sapos y lagartijas."]},"solucion":{}},{"slug":"animales-2.s5.p8","orden":8,"grupo":"animales-2.s5.p8","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué elementos crean hábitat para la fauna en un jardín? Marcá todos.","opciones":[{"id":"o1","texto":"Plantas nativas con flores y frutos"},{"id":"o2","texto":"Un plato bajo con agua limpia que se cambia seguido"},{"id":"o3","texto":"Arbustos densos"},{"id":"o4","texto":"Un rincón con hojas secas"},{"id":"o5","texto":"Césped corto con herbicidas en todo el terreno"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Agua, refugio y comida: las tres cosas que busca cualquier animal."}},{"slug":"animales-2.s5.p9","orden":9,"grupo":"animales-2.s5.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada elemento con el animal al que más ayuda.","izquierda":[{"id":"a1","texto":"Caja nido"},{"id":"a2","texto":"Rincón con hojas secas"},{"id":"a3","texto":"Flores nativas"},{"id":"a4","texto":"Refugio para murciélagos"}],"derecha":[{"id":"b1","texto":"Aves que anidan en huecos"},{"id":"b2","texto":"Sapos, lagartijas e insectos"},{"id":"b3","texto":"Mariposas y abejas"},{"id":"b4","texto":"Murciélagos insectívoros"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada elemento suma un tipo de hábitat distinto."}},{"slug":"animales-2.s5.p10","orden":10,"grupo":"animales-2.s5.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un ventanal mide 10 metros de ancho. Si se ponen marcas verticales cada 5 centímetros, ¿cuántas franjas hacen falta aproximadamente? (Dividí el ancho en cm por la separación)","unidad":"marcas","decimales":0},"solucion":{"valor":200,"tolerancia":4,"explicacion":"10 m = 1000 cm; 1000 ÷ 5 = 200 marcas. Con marcas tan juntas, las aves perciben el vidrio como un obstáculo."}},{"slug":"animales-2.s5.p10.v2","orden":10,"grupo":"animales-2.s5.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un ventanal mide 20 metros de ancho. Si se ponen marcas verticales cada 10 centímetros, ¿cuántas franjas hacen falta aproximadamente? (Dividí el ancho en cm por la separación)","unidad":"marcas","decimales":0},"solucion":{"valor":200,"tolerancia":4,"explicacion":"20 m = 2000 cm; 2000 ÷ 10 = 200 marcas. Con marcas tan juntas, las aves perciben el vidrio como un obstáculo."}},{"slug":"animales-2.s5.p10.v3","orden":10,"grupo":"animales-2.s5.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un ventanal mide 6 metros de ancho. Si se ponen marcas verticales cada 5 centímetros, ¿cuántas franjas hacen falta aproximadamente? (Dividí el ancho en cm por la separación)","unidad":"marcas","decimales":0},"solucion":{"valor":120,"tolerancia":2.4,"explicacion":"6 m = 600 cm; 600 ÷ 5 = 120 marcas. Con marcas tan juntas, las aves perciben el vidrio como un obstáculo."}},{"slug":"animales-2.s5.p11","orden":11,"grupo":"animales-2.s5.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un herbicida para dejar el césped perfecto no afecta a la fauna del jardín.","razones":[{"id":"r1","texto":"Porque elimina alimento y puede dañar a sapos, insectos y aves"},{"id":"r2","texto":"Porque los herbicidas atraen mariposas"},{"id":"r3","texto":"Porque la fauna no vive en jardines"}]},"solucion":{"valor":false,"explicacion":"Elimina plantas que alimentan insectos y puede afectar a sapos, insectos y aves. Un jardín con algo de diversidad es mucho mejor hábitat.","clave":["r1"]}},{"slug":"animales-2.s5.p12","orden":12,"grupo":"animales-2.s5.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan de un edificio y marcá lo que no ayuda a la fauna.","segmentos":[{"id":"s1","texto":"Pondremos marcas en los ventanales del hall."},{"id":"s2","texto":"Dejaremos los reflectores del frente encendidos toda la noche apuntando al cielo."},{"id":"s3","texto":"Plantaremos nativas en el cantero de la entrada."},{"id":"s4","texto":"Pondremos una sola calcomanía de halcón en el ventanal."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los detalles importan: cantidad de marcas, dirección de la luz.","por_opcion":{"s2":"La luz hacia el cielo desorienta aves e insectos y gasta energía.","s4":"Una silueta aislada casi no sirve: hacen falta marcas repartidas."}}},{"slug":"animales-2.s5.p13","orden":13,"grupo":"animales-2.s5.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las aves no ven los {{0}}; la luz de noche conviene que apunte hacia {{1}}; y un jardín amigo de la fauna ofrece agua, refugio y {{2}}.","banco":[{"id":"w1","texto":"vidrios"},{"id":"w2","texto":"abajo"},{"id":"w3","texto":"comida"},{"id":"w4","texto":"techos"},{"id":"w5","texto":"arriba"},{"id":"w6","texto":"ruido"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres cambios chicos para una ciudad más amable."}}]},{"slug":"animales-2.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: vecinos silvestres","bajada_es":"Fauna urbana, convivencia, mascotas, tráfico y ciudad amigable, mezclados.","minutos":8,"pasos":[{"slug":"animales-2.s6.p1","orden":1,"grupo":"animales-2.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Vecinos silvestres». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"animales-2.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el barrio junto al humedal","bajada_es":"Un barrio nuevo junto a un humedal tiene conflictos con la fauna. Ordená los problemas y armá un plan de convivencia.","minutos":10,"pasos":[{"slug":"animales-2.s7.p1","orden":1,"grupo":"animales-2.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El barrio","cuerpo":["Un barrio de 300 casas se construyó al lado de un humedal. Los vecinos se quejan de que los carpinchos comen los jardines y cruzan las calles, y algunos proponen echarlos. Hay 180 perros y 150 gatos, muchos sueltos. En la entrada hay un edificio vidriado donde aparecen aves muertas cada semana, y las luces del perímetro quedan encendidas toda la noche.","En el humedal viven carpinchos, garzas, teros, coipos y muchas otras especies. La asociación vecinal pidió un plan de convivencia."]},"solucion":{}},{"slug":"animales-2.s7.p2","orden":2,"grupo":"animales-2.s7.p2","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es el enfoque correcto para el conflicto con los carpinchos?","opciones":[{"id":"o1","texto":"Convivir con reglas claras"},{"id":"o2","texto":"Capturarlos y llevarlos a otro lugar"},{"id":"o3","texto":"Cazarlos para reducir la población"},{"id":"o4","texto":"Cerrar el humedal y rellenarlo"}]},"solucion":{"clave":["o1"],"explicacion":"El barrio se instaló en su ambiente. La salida es la convivencia, no la expulsión.","por_opcion":{"o3":"Es ilegal y no resuelve nada: el humedal es su hábitat."}}},{"slug":"animales-2.s7.p3","orden":3,"grupo":"animales-2.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si cada gato suelto caza en promedio 10 aves por año, ¿cuántas aves por año cazarían los 150 gatos del barrio si todos salieran?","unidad":"aves","decimales":0,"contexto":"150 gatos; 10 aves por gato por año."},"solucion":{"valor":1500,"tolerancia":30,"explicacion":"150 × 10 = 1.500 aves por año, en el borde de un humedal lleno de aves."}},{"slug":"animales-2.s7.p4","orden":4,"grupo":"animales-2.s7.p4","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las medidas del plan por su prioridad, de la primera a la última.","items":[{"id":"i1","texto":"Correa obligatoria y gatos adentro de noche en el borde del humedal"},{"id":"i2","texto":"Marcas en los vidrios del edificio de la entrada"},{"id":"i3","texto":"Luces del perímetro hacia abajo y con sensor"},{"id":"i4","texto":"Carteles y charlas sobre convivencia con carpinchos"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero lo que evita muertes ya; después lo que mejora el hábitat y los hábitos.","valores":{"i1":"protege a la fauna ya","i2":"evita muertes cada semana","i3":"reduce la desorientación","i4":"cambia hábitos a largo plazo"}}},{"slug":"animales-2.s7.p5","orden":5,"grupo":"animales-2.s7.p5","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las propuestas de los vecinos.","grupos":[{"id":"g1","nombre":"Suma a la convivencia"},{"id":"g2","nombre":"Empeora la situación"}],"items":[{"id":"i1","texto":"Reductores de velocidad en la calle junto al humedal"},{"id":"i2","texto":"Darles pan a los carpinchos para que no coman los jardines"},{"id":"i3","texto":"Cercos bajos para proteger huertas"},{"id":"i4","texto":"Soltar perros de noche para ahuyentarlos"},{"id":"i5","texto":"Castración gratuita de perros y gatos"},{"id":"i6","texto":"Rellenar una parte del humedal"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las buenas medidas protegen a vecinos y fauna; las malas aumentan el conflicto o destruyen hábitat."}},{"slug":"animales-2.s7.p6","orden":6,"grupo":"animales-2.s7.p6","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Alimentar a los carpinchos en un lugar fijo reduciría el problema de los jardines.","razones":[{"id":"r1","texto":"Porque los acostumbra a las personas y los concentra"},{"id":"r2","texto":"Porque los carpinchos no comen pasto"},{"id":"r3","texto":"Porque la comida los vuelve silvestres otra vez"}]},"solucion":{"valor":false,"explicacion":"Los acostumbraría a las personas, los concentraría y aumentaría los conflictos y las enfermedades. No hay que alimentarlos.","clave":["r1"]}},{"slug":"animales-2.s7.p7","orden":7,"grupo":"animales-2.s7.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué debería incluir el plan sobre las mascotas? Marcá todo.","opciones":[{"id":"o1","texto":"Perros con correa en las calles junto al humedal"},{"id":"o2","texto":"Gatos adentro de noche"},{"id":"o3","texto":"Campaña de castración"},{"id":"o4","texto":"Prohibir abandonar animales"},{"id":"o5","texto":"Dejar que los perros persigan carpinchos para que se vayan"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Las mascotas bien cuidadas conviven mejor con el humedal, y también están más seguras."}},{"slug":"animales-2.s7.p8","orden":8,"grupo":"animales-2.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La asociación publica su plan. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Pondremos marcas en los vidrios del edificio de la entrada."},{"id":"s2","texto":"Pediremos que trasladen a los carpinchos a otra provincia."},{"id":"s3","texto":"Las luces del perímetro apuntarán hacia abajo y tendrán sensores."},{"id":"s4","texto":"Cada vecino podrá dar de comer a los carpinchos en su jardín."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un plan de convivencia protege a la fauna en su hábitat y cambia los hábitos de las personas.","por_opcion":{"s2":"El humedal es su hábitat; trasladarlos no resuelve el conflicto y puede dañarlos.","s4":"Alimentarlos aumenta los conflictos y las enfermedades."}}}]}]}$ac$::jsonb);
